const IMAGE_ACCEL_BASES = [
    'https://littleaibox.oss-accelerate.aliyuncs.com'
];
const ACCEL_FETCH_TIMEOUT_MS = 8000;
const ANDROID_PICTURES_DIR = 'Pictures/LittleAIBox';
