const willChangeTimers = new WeakMap();

function applyTemporaryWillChange(entries, durationMs = 300) {
    const items = Array.isArray(entries) ? entries : [entries];
    items.forEach((item) => {
        const element = item.element;
        if (!element) return;
        element.style.willChange = item.value;
        const existingTimer = willChangeTimers.get(element);
        if (existingTimer) {
            clearTimeout(existingTimer);
        }
        const timer = setTimeout(() => {
            element.style.willChange = '';
            willChangeTimers.delete(element);
        }, durationMs);
        willChangeTimers.set(element, timer);
    });
}

function openSidebar() {
    const isMobile = window.matchMedia('(max-width: 640px)').matches;
    applyTemporaryWillChange([
        { element: elements.sidebar, value: 'transform' },
        { element: document.body, value: 'padding-left' },
        { element: document.querySelector('.chat-area'), value: 'margin-left, margin-right' },
        { element: document.getElementById('sidebar-toggle-btn')?.querySelector('svg'), value: 'transform' }
    ]);
    if (isMobile) {
        document.body.classList.add('sidebar-open');
    } else {
        document.body.classList.remove('sidebar-collapsed');
    }
    document.getElementById('sidebar-toggle-btn').setAttribute('aria-expanded', 'true');
    navigationEngine?.notifySidebarOpened?.();
}

function closeSidebar(isFromBackButton = false, options = {}) {
    const isMobile = window.matchMedia('(max-width: 640px)').matches;
    const shouldCloseMobile = isMobile && document.body.classList.contains('sidebar-open');
    const shouldCloseDesktop = !isMobile && !document.body.classList.contains('sidebar-collapsed');

    if (!shouldCloseMobile && !shouldCloseDesktop) {
        return;
    }

    applyTemporaryWillChange([
        { element: elements.sidebar, value: 'transform' },
        { element: document.body, value: 'padding-left' },
        { element: document.querySelector('.chat-area'), value: 'margin-left, margin-right' },
        { element: document.getElementById('sidebar-toggle-btn')?.querySelector('svg'), value: 'transform' }
    ]);

    queueMicrotask(() => {
        if (isMobile) {
            document.body.classList.remove('sidebar-open');
        } else {
            document.body.classList.add('sidebar-collapsed');
        }

        const toggle = document.getElementById('sidebar-toggle-btn');
        if (toggle) toggle.setAttribute('aria-expanded', 'false');
        const fromHistory = options.fromHistory === true;
        navigationEngine?.notifySidebarClosed?.({ fromHistory });
    });
}

function closeSidebarOnInteraction() {
    const isMobile = window.matchMedia('(max-width: 640px)').matches;
    const sidebarToggleBtn = document.getElementById('sidebar-toggle-btn');
    if (isMobile) {
        closeSidebar();
    } else {
        document.body.classList.add('sidebar-collapsed');
        sidebarToggleBtn.setAttribute('aria-expanded', 'false');
    }
}

