function getChatSortTimestamp(chat) {
    if (!chat) return 0;
    const updatedAt = Date.parse(chat.updated_at || '');
    if (!Number.isNaN(updatedAt)) return updatedAt;
    const createdAt = Date.parse(chat.created_at || '');
    if (!Number.isNaN(createdAt)) return createdAt;
    return 0;
}

function touchChatUpdatedAt(chatId, timestampMs = null) {
    if (!chatId || !chats[chatId]) return;
    const safeMs = Number.isFinite(timestampMs) ? timestampMs : Date.now();
    const iso = new Date(safeMs).toISOString();
    chats[chatId].updated_at = iso;
    if (!chats[chatId].created_at) {
        chats[chatId].created_at = iso;
    }
}

function sortChatIdsForSidebar(ids) {
    return ids.sort((a, b) => {
        const chatA = chats[a];
        const chatB = chats[b];
        const aIsNew = chatA?.isTemp || chatA?.isNewlyCreated;
        const bIsNew = chatB?.isTemp || chatB?.isNewlyCreated;
        if (aIsNew && !bIsNew) return -1;
        if (!aIsNew && bIsNew) return 1;
        const timeA = getChatSortTimestamp(chatA);
        const timeB = getChatSortTimestamp(chatB);
        if (timeA !== timeB) return timeB - timeA;
        return 0;
    });
}

function getSidebarRootChatIds() {
    const rootIds = Object.keys(chats).filter((chatId) => {
        const chat = chats[chatId];
        return chat && !bridgeFeature.isBridgeChildChat(chat);
    });
    return sortChatIdsForSidebar(rootIds);
}

function renderSidebar() {
    const loader = document.getElementById('chat-history-loader');
    if (loader) {
        if (!chatHistoryLoading) {
            loader.style.display = 'none';
        }
    }

    const rootChatIds = getSidebarRootChatIds();
    const fragment = document.createDocumentFragment();
    sidebarElementsCache.clear();

    rootChatIds.forEach((id) => {
        const chatData = chats[id];
        if (!chatData) return;

        const { bridgeFeatureEnabled, bridgeEnabled, childIds, bridgeExpanded } = resolveBridgeRenderState({
            currentUser,
            id,
            currentChatId,
            isBridgeEnabled: bridgeFeature.isBridgeEnabled,
            getBridgeChildIds: bridgeFeature.getBridgeChildIds,
            isBridgeExpanded: bridgeFeature.isBridgeExpanded,
            setBridgeExpanded: bridgeFeature.setBridgeExpanded
        });

        const rootItem = createHistoryItem(id, chatData, currentChatId, {
            bridgeEnabled,
            bridgeExpanded,
            bridgeChild: false
        });
        sidebarElementsCache.set(id, rootItem);
        fragment.appendChild(rootItem);

        if (!bridgeFeatureEnabled || !bridgeEnabled || !bridgeExpanded) {
            return;
        }

        childIds.forEach((childId) => {
            const childData = chats[childId];
            if (!childData) return;
            const childItem = createHistoryItem(childId, childData, currentChatId, {
                bridgeEnabled: false,
                bridgeExpanded: false,
                bridgeChild: true
            });
            sidebarElementsCache.set(childId, childItem);
            fragment.appendChild(childItem);
        });

        const newBridgeItem = bridgeFeature.createBridgeNewItem(id);
        fragment.appendChild(newBridgeItem);
    });

    if (elements.chatHistoryList) {
        elements.chatHistoryList.querySelectorAll('.history-item').forEach(el => el.remove());
        elements.chatHistoryList.querySelectorAll('.bridge-new-item').forEach(el => el.remove());
        const anchor = loader && loader.parentNode === elements.chatHistoryList ? loader : null;
        if (anchor) {
            elements.chatHistoryList.insertBefore(fragment, anchor);
        } else {
            elements.chatHistoryList.appendChild(fragment);
        }
    }

    refreshExportRecordsUi();
}

function createHistoryItem(id, chatData, currentChatId, options = {}) {
    const { bridgeEnabled = false, bridgeExpanded = false, bridgeChild = false } = options;
    const li = document.createElement('li');
    li.className = 'history-item';
    if (bridgeChild) {
        li.classList.add('history-item-bridge-child');
    }
    if (bridgeEnabled) {
        li.classList.add('history-item-bridge-parent');
    }
    li.dataset.chatId = id;
    if (id === currentChatId) li.classList.add('active');

    const checkboxLabel = document.createElement('label');
    checkboxLabel.className = 'history-item-checkbox-container';
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.className = 'history-item-checkbox';
    checkbox.name = 'history-select';
    checkbox.dataset.chatId = id;
    checkbox.checked = selectedChatIds.has(id);
    const checkmark = document.createElement('span');
    checkmark.className = 'checkmark';
    checkboxLabel.appendChild(checkbox);
    checkboxLabel.appendChild(checkmark);

    attachBridgeVisualElements(li, {
        bridgeChild,
        bridgeEnabled,
        bridgeExpanded,
        id,
        currentUser,
        getToastMessage
    });

    const title = document.createElement('span');
    title.className = 'title';
    title.textContent = chatData.title;

    const actionsDiv = document.createElement('div');
    actionsDiv.className = 'history-actions';

    const menuBtn = document.createElement('button');
    menuBtn.className = 'action-menu-btn';
    menuBtn.setAttribute('aria-label', getToastMessage('ui.moreActions'));
    menuBtn.innerHTML = '<svg viewBox="0 0 24 24" width="20" height="20"><path d="M12 8c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm0 2c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2zm0 6c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2z"/></svg>';

    const contextMenu = document.createElement('div');
    contextMenu.className = 'context-menu';

    menuBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        openContextMenu(contextMenu, menuBtn);
    });

    const isMobile = window.matchMedia('(max-width: 640px)').matches;

    if (isMobile) {
        document.addEventListener('click', (e) => {
            if (!contextMenu.contains(e.target) && !menuBtn.contains(e.target)) {
                closeActiveContextMenu();
            }
        });
    }

    const renameBtn = createMenuButton('rename', ICONS.EDIT, getToastMessage('ui.rename'));
    contextMenu.appendChild(renameBtn);

    const copyTitleBtn = createMenuButton(
        'copy-title',
        `<svg viewBox="0 0 24 24"><path d="${ICONS.COPY}"/></svg>`,
        getToastMessage('ui.copyTitle')
    );
    contextMenu.appendChild(copyTitleBtn);

    const isBridgeConversation = !!chatData?.isBridge;
    appendBridgeMenuItems(contextMenu, {
        chatData,
        id,
        bridgeChild,
        currentUser,
        getToastMessage,
        createMenuButton,
        shouldShowBridgeToggle: bridgeFeature.shouldShowBridgeToggle,
        isBridgeEnabled: bridgeFeature.isBridgeEnabled
    });

    if (!isBridgeConversation) {
        if (currentUser && isChatPromoted(id, chatData)) {
            const shareBtn = createMenuButton('share', ICONS.SHARE, getToastMessage('ui.share'));
            contextMenu.appendChild(shareBtn);
        }

        const multiSelectBtn = createMenuButton('multi-select', '<svg viewBox="0 0 24 24"><path d="M7 17h14v-2H7v2zm0-4h14v-2H7v2zm0-4h14V7H7v2zM4 17.27L1.27 14.54l1.41-1.41L4 14.44l3.12-3.12 1.41 1.41L4 17.27zM5.41 9.96L4 8.54 1.27 11.27l1.41 1.41L4 11.39l3.12-3.12-1.41-1.41L4.29 8.29zM4 5.73L1.27 3l1.41-1.41L4 2.9l3.12-3.12 1.41 1.41L4 5.73z"/></svg>', getToastMessage('ui.multiSelect'));
        contextMenu.appendChild(multiSelectBtn);
    }

    const deleteBtn = createMenuButton('delete', ICONS.DELETE, getToastMessage('ui.delete'));
    contextMenu.appendChild(deleteBtn);

    actionsDiv.appendChild(menuBtn);

    li.appendChild(checkboxLabel);
    li.appendChild(title);
    li.appendChild(actionsDiv);
    li.appendChild(contextMenu);

    return li;
}

function createMenuButton(action, icon, text) {
    const btn = document.createElement('button');
    btn.dataset.action = action;
    btn.innerHTML = `${icon}<span>${text}</span>`;
    return btn;
}

function setActiveChat(chatId) {
    const currentActive = elements.chatHistoryList.querySelector('.history-item.active');
    if (currentActive && currentActive.dataset.chatId !== chatId) {
        currentActive.classList.remove('active');
    }
    if (chatId) {
        const newActive = elements.chatHistoryList.querySelector(`.history-item[data-chat-id="${chatId}"]`);
        if (newActive && !newActive.classList.contains('active')) {
            newActive.classList.add('active');
        }
    }
}

function updateSidebarChatId(oldId, newId) {
    if (!oldId || !newId || oldId === newId) return;
    const existingItem = sidebarElementsCache.get(oldId);
    if (!existingItem) return;

    // Remove any stale cache entry mapped to the new ID
    if (sidebarElementsCache.has(newId)) {
        const duplicate = sidebarElementsCache.get(newId);
        if (duplicate && duplicate !== existingItem) {
            duplicate.remove();
        }
        sidebarElementsCache.delete(newId);
    }

    existingItem.dataset.chatId = newId;
    const checkbox = existingItem.querySelector('.history-item-checkbox');
    if (checkbox) {
        checkbox.dataset.chatId = newId;
    }

    sidebarElementsCache.delete(oldId);
    sidebarElementsCache.set(newId, existingItem);

    if (selectedChatIds.has(oldId)) {
        selectedChatIds.delete(oldId);
        selectedChatIds.add(newId);
        if (checkbox) {
            checkbox.checked = true;
        }
    }

    if (currentChatId === newId) {
        setActiveChat(newId);
    }
}

function scheduleRenderSidebar() {
    if (renderSidebarRequested) return;
    if (renderSidebarTimer) return;

    renderSidebarRequested = true;

    renderSidebarTimer = setTimeout(() => {
        if (window.requestIdleCallback) {
            requestIdleCallback(() => {
                renderSidebar();
                renderSidebarTimer = null;
                renderSidebarRequested = false;
            }, { timeout: 500 });
        } else {
            requestAnimationFrame(() => {
                renderSidebar();
                renderSidebarTimer = null;
                renderSidebarRequested = false;
            });
        }
    }, 50);
}

async function renameChat(chatId) {
    const oldTitle = chats[chatId].title;
    const newTitle = await showCustomPrompt(getToastMessage('dialog.renameConversation'), getToastMessage('dialog.enterNewChatTitle'), oldTitle);

    if (newTitle && newTitle.trim() !== "" && newTitle.trim() !== oldTitle) {
        const trimmedTitle = newTitle.trim();

        try {
            if (currentUser) {
                const response = await fetch(`/api/chats/conversations`, {
                    method: 'PUT',
                    headers: {
                        'Content-Type': 'application/json',
                        'X-Session-ID': sessionId
                    },
                    body: JSON.stringify({
                        conversationId: chatId,
                        title: trimmedTitle
                    })
                });

                if (!response.ok) {
                    const errorData = await response.json();
                    throw new Error(errorData.error || `${getToastMessage('errors.requestFailed')}: ${response.status}`);
                }

                const result = await response.json();
                if (!result.success) {
                    throw new Error(result.error || getToastMessage('errors.apiRequestFailed'));
                }
            }

            chats[chatId].title = trimmedTitle;
            if (!currentUser) {
                await saveChatsToDB('guest', chats);
            } else {
                await saveChatsToDB(currentUser.id, chats);
            }

            scheduleRenderSidebar();
            showToast(getToastMessage('toast.renameSuccess'), 'success');
            notifyBackendCacheInvalidation('chat_title_updated', { chatId, oldTitle, newTitle: trimmedTitle });

        } catch (error) {
            console.error(`${getToastMessage('console.renameFailed')}:`, error);

            chats[chatId].title = oldTitle;
            scheduleRenderSidebar();
            showToast(`${getToastMessage('toast.renameFailed')}: ${error.message}`, 'error');
        }
    }
}

async function shareChat(chatId) {
    if (!currentUser) {
        showToast(getToastMessage('toast.loginRequiredForShare'), 'info');
        return;
    }

    try {
        showToast(getToastMessage('toast.generatingShareLink'), 'info');

        // 获取用户当前应用显示的语言
        const currentLang = currentUser ? (currentUser.language || getCurrentLanguage()) : getCurrentLanguage();

        const result = await makeApiRequest(`chats/${chatId}/share`, {
            method: 'POST',
            body: JSON.stringify({ language: currentLang })
        });

        if (result.success && result.url) {
            navigator.clipboard.writeText(result.url).then(() => {
                showToast(getToastMessage('toast.linkCopiedToClipboard'), 'success');
            }).catch(() => {
                showToast(getToastMessage('toast.linkGeneratedCopyFailed'), 'warning');
                showCustomPrompt(getToastMessage('ui.shareLink'), getToastMessage('ui.pleaseCopyLinkManually'), result.url);
            });
        } else {
            throw new Error(result.error || getToastMessage('errors.cannotGenerateLink'));
        }
    } catch (error) {
        showToast(`${getToastMessage('toast.shareFailed')}: ${error.message}`, 'error');
    } finally {
        document.querySelectorAll('.context-menu').forEach(menu => menu.style.display = 'none');
    }
}

async function deleteChat(chatId, showConfirmation = true, isBatchOperation = false) {
    const chatToDelete = chats[chatId];
    if (!chatToDelete) {

        return;
    }
    const confirmed = showConfirmation ? await showCustomConfirm(getToastMessage('dialog.deleteConversation'), getToastMessage('dialog.deleteConversationMessage', { title: chatToDelete.title || getToastMessage('dialog.thisConversation') }), ICONS.DELETE) : true;

    if (!confirmed) {
        return;
    }
    const childIds = bridgeFeature.getBridgeChildIds(chatId);
    const allDeleteIds = [chatId, ...childIds];
    const deletedChats = [];
    const isDeletingCurrentChat = allDeleteIds.includes(currentChatId);

    allDeleteIds.forEach((id) => {
        if (!chats[id]) return;
        deletedChats.push(chats[id]);
        delete chats[id];
        bridgeFeature.clearBridgeState(id);
        localStorage.removeItem(`pending_chat_${id}`);
    });
    bridgeFeature.setBridgeEnabled(chatId, false);
    bridgeFeature.setBridgeExpanded(chatId, false);

    if (!currentUser) {
        await saveChatsToDB('guest', chats);
    }
    scheduleRenderSidebar();

    if (isDeletingCurrentChat) {
        currentChatId = null;
        welcomePageShown = false;
        streamImageRuntime.clearPendingImagePlaceholdersInChatContainer();
        showEmptyState();
        scheduleRenderSidebar();
        routeManager.navigateToHome({ replace: true });
    }

    try {
        if (currentUser) {
            for (const id of allDeleteIds) {
                if (String(id).startsWith('temp_')) continue;
                const response = await makeApiRequest(`chats/${id}`, { method: 'DELETE' });
                if (!response.success) {
                    throw new Error(response.error || getToastMessage('errors.serverCannotDeleteConversation'));
                }
            }
            await saveChatsToDB(currentUser.id, chats);
        }
        await cleanupDocumentImagesForDeletedChats(deletedChats);

        if (showConfirmation) {
            showToast(getToastMessage('toast.conversationDeleted'), 'success');
            if (currentUser) {
                notifyBackendCacheInvalidation('chat_deleted', { chatId, deletedIds: allDeleteIds });
            }
        } else {

        }

        allDeleteIds.forEach((id) => {
            if (activeResponses.has(id)) {
                activeResponses.get(id).controller.abort();
                activeResponses.delete(id);
            }
        });

    } catch (error) {
        showToast(`${getToastMessage('toast.deleteFailed')}: ${error.message}`, 'error');

        deletedChats.forEach((chat) => {
            if (chat?.id) {
                chats[chat.id] = chat;
            }
        });
        scheduleRenderSidebar();

        if (isDeletingCurrentChat) {
            loadChat(chatId);
        }
    } finally {
        document.querySelectorAll('.context-menu').forEach(menu => menu.style.display = 'none');
    }
}

const KATEX_CONFIG = {
    delimiters: [
        { left: '$$', right: '$$', display: true },
        { left: '$', right: '$', display: false },
        { left: '\\(', right: '\\)', display: false },
        { left: '\\[', right: '\\]', display: true }
    ],
    throwOnError: false,
    strict: false,
    trust: true,
    ignoredTags: ['script', 'noscript', 'style', 'textarea', 'pre', 'code'],
    macros: {
        // 常用数学集合简写
        "\\RR": "\\mathbb{R}",
        "\\NN": "\\mathbb{N}",
        "\\ZZ": "\\mathbb{Z}",
        "\\QQ": "\\mathbb{Q}",
        "\\CC": "\\mathbb{C}",

        // 逻辑符号
        "\\lnot": "\\neg ",

        // 量子力学符号
        "\\bra": "\\langle #1 |",
        "\\ket": "| #1 \\rangle",
        "\\braket": "\\langle #1 | #2 \\rangle",

        // 矢量箭头
        "\\vec": "\\overrightarrow{#1}",
        "\\vect": "\\overrightarrow{#1}"
    }
};

class MathRenderer {
    constructor(katexConfig) {
        this.katexConfig = katexConfig;
        this.partialConfig = {
            delimiters: katexConfig.delimiters,
            throwOnError: false,
            strict: false,
            trust: true,
            macros: katexConfig.macros
        };

        this.inlinePatternSource = MathRenderer.buildInlinePatternSource();
        this.displayLineRegex = MathRenderer.buildDisplayLineRegex();
    }

    static get COMMAND_PATTERN() {
        return '(?:frac|sqrt|sum|int|prod|lim|log|ln|sin|cos|tan|cot|sec|csc|sinh|cosh|tanh|arcsin|arccos|arctan|pi|mu|nu|alpha|beta|gamma|delta|epsilon|lambda|theta|phi|psi|omega|chi|eta|zeta|xi|rho|sigma|tau|upsilon|kappa|varphi|varpi|varsigma|vartheta|Phi|Psi|Omega|Delta|Gamma|Lambda|Sigma|Pi|Theta|Chi|cdot|times|neq|leq|geq|approx|sim|infty|partial|nabla|mathbb|mathrm|mathbf|mathcal|boldsymbol|operatorname|overline|underline|widehat|widetilde|hat|vec|bar|tilde|dot|ddot|ce|binom|left|right|text|displaystyle|mathsf|mathtt|mathfrak|mathit)';
    }

    static get UNICODE_TEXT_CLASS() {
        return '\\p{L}\\p{N}\\p{M}\\p{P}\\p{S}\\p{Zs}';
    }

    static buildInlinePatternSource() {
        const chars = `${MathRenderer.UNICODE_TEXT_CLASS}0-9\\s+\\-*/^_=()\\\\.,·:;`;
        return `([${chars}]*\\\\${MathRenderer.COMMAND_PATTERN}[${chars}{}]*)`;
    }

    static buildDisplayLineRegex() {
        const chars = `${MathRenderer.UNICODE_TEXT_CLASS}0-9\\s\\\\{}^_*+\\-=/().,:;·`;
        return new RegExp(`^[${chars}]+$`, 'u');
    }

    preprocessMarkdown(text) {
        let result = this.normalizeLatexEnvironments(text);
        result = this.promoteStandaloneInlineMath(result);
        return result;
    }

    normalizeLatexEnvironments(text) {
        let result = text;
        const protectedRanges = [];
        const dollarBlockRegex = /\$\$([\s\S]*?)\$\$/g;
        let match;
        while ((match = dollarBlockRegex.exec(text)) !== null) {
            protectedRanges.push({
                start: match.index,
                end: match.index + match[0].length
            });
        }

        result = result.replace(/\\begin\s*\{([A-Za-z0-9*]+)\}([\s\S]*?)\\end\s*\{\1\}/gmi, (match, envName, content, offset) => {
            const isProtected = protectedRanges.some(range =>
                offset >= range.start && offset < range.end
            );

            if (isProtected) {
                return match;
            }
            let fixedContent = content.replace(/([^\\]|^)\\(\s)/g, '$1\\\\$2');
            return `$$\\begin{${envName}}${fixedContent}\\end{${envName}}$$`;
        });

        return result;
    }

    promoteStandaloneInlineMath(text) {
        try {
            const lines = text.split(/\r?\n/);
            let fence = null;
            for (let i = 0; i < lines.length; i++) {
                const line = lines[i];
                const fenceMatch = line.match(/^\s{0,3}([`~]{3,})(.*)$/);
                if (fenceMatch) {
                    const ch = fenceMatch[1][0];
                    const len = fenceMatch[1].length;
                    if (!fence) {
                        fence = { ch, len };
                    } else if (fence && ch === fence.ch && len >= fence.len) {
                        fence = null;
                    }
                    continue;
                }

                if (fence) continue;

                const trimmed = line.trim();
                const match = trimmed.match(/^\$([^$\n]+)\$/);
                if (match) {
                    const before = line.slice(0, line.indexOf(trimmed));
                    const after = line.slice(line.indexOf(trimmed) + trimmed.length);
                    lines[i] = `${before}$$${match[1]}$$${after}`;
                }
            }
            return lines.join('\n');
        } catch (_) {
            return text;
        }
    }

    wrapBareInlineLatexCommands(text) {
        try {
            const lines = text.split(/\r?\n/);
            let fence = null;
            const inlineRegex = new RegExp(this.inlinePatternSource, 'gu');
            const hasExplicitMathDelimiters = (line) =>
                line.includes('$') || line.includes('\\(') || line.includes('\\)') || line.includes('\\[') || line.includes('\\]');

            const maybeWrapMathSegment = (segment) => {
                const raw = String(segment || '');
                const trimmed = raw.trim();
                if (!trimmed) return null;
                const classified = this.classifyMathLikeContent(trimmed);
                if (!classified?.shouldWrap || !classified.mathBody) return null;

                const strongMathSignal = /[_^]|(?:^|[^A-Za-z])\d+\s*[=+\-*/]|[=+\-*/]\s*\d+|[=+\-*/].*[_^]/u.test(trimmed);
                if (!strongMathSignal) return null;
                return `$$${classified.mathBody}$$`;
            };

            for (let i = 0; i < lines.length; i++) {
                const line = lines[i];
                const fenceMatch = line.match(/^\s{0,3}([`~]{3,})(.*)$/);
                if (fenceMatch) {
                    const ch = fenceMatch[1][0];
                    const len = fenceMatch[1].length;
                    if (!fence) {
                        fence = { ch, len };
                    } else if (fence && ch === fence.ch && len >= fence.len) {
                        fence = null;
                    }
                    continue;
                }

                if (fence) continue;
                if (hasExplicitMathDelimiters(line)) {
                    continue;
                }
                if (/\\begin\s*\{[A-Za-z0-9*]+\}/u.test(line)) {
                    continue;
                }

                // 1) “说明文字：公式”场景，仅包裹冒号后的公式段
                const colonMatch = line.match(/^(\s*[^:：\n]{0,80}[：:]\s*)(.+)$/u);
                if (colonMatch) {
                    const wrapped = maybeWrapMathSegment(colonMatch[2]);
                    if (wrapped) {
                        lines[i] = `${colonMatch[1]}${wrapped}`;
                        continue;
                    }
                }

                // 2) 整行本身就是明显数学表达式
                const wholeLineWrapped = maybeWrapMathSegment(line);
                if (wholeLineWrapped) {
                    lines[i] = wholeLineWrapped;
                    continue;
                }

                if (!line.includes('\\')) continue;

                const trimmed = line.trim();
                inlineRegex.lastIndex = 0;
                if (trimmed && this.displayLineRegex.test(trimmed) && inlineRegex.test(trimmed)) {
                    lines[i] = `$$${trimmed}$$`;
                    continue;
                }

                const parts = line.split('`');
                for (let p = 0; p < parts.length; p += 2) {
                    parts[p] = parts[p].replace(inlineRegex, (match) => {
                        const trimmed = match.trim();
                        if (!trimmed) return match;
                        return `$${trimmed}$`;
                    });
                }
                lines[i] = parts.join('`');
            }
            return lines.join('\n');
        } catch (_) {
            return text;
        }
    }

    classifyMathLikeContent(trimmed) {
        if (!trimmed) {
            return { shouldWrap: false, mathBody: trimmed };
        }

        const commandRegex = this.commandRegex();
        commandRegex.lastIndex = 0;

        let looksLikeMath = trimmed.includes('\\') || commandRegex.test(trimmed);

        if (!looksLikeMath) {
            const superscriptPattern = /(?:^|[^A-Za-z0-9])([A-Za-z0-9])\s*\^\s*(?:\{?[A-Za-z0-9+\-*/]+\}?|[A-Za-z0-9])/u;
            const subscriptPattern = /(?:^|[^A-Za-z0-9])([A-Za-z0-9])\s*_\s*(?:\{?[A-Za-z0-9]+\}?)/u;
            const operatorPattern = /[=+\-*/]/u;
            const fractionPattern = /[A-Za-z0-9]\s*\/\s*[A-Za-z0-9]/u;
            const greekPattern = /[α-ωΑ-ΩπμθσρλντφψΩΦΛΣΠΘΧβγδεζηξρ]/u;
            const symbolPattern = /[∑∏√∞≈≠≤≥±÷×⋅·]/u;

            looksLikeMath =
                superscriptPattern.test(trimmed) ||
                subscriptPattern.test(trimmed) ||
                (operatorPattern.test(trimmed) && this.isAsciiMathContent(trimmed)) ||
                fractionPattern.test(trimmed) ||
                greekPattern.test(trimmed) ||
                symbolPattern.test(trimmed);
        }

        if (looksLikeMath) {
            return { shouldWrap: true, mathBody: this.normalizeMathBody(trimmed) };
        }

        if (this.isLikelyShortMathToken(trimmed)) {
            return { shouldWrap: true, mathBody: this.normalizeMathBody(trimmed) };
        }

        if (this.looksLikeChemicalEquation(trimmed)) {
            const needsCeWrap = !/^\\ce\{.*\}$/u.test(trimmed);
            const chemicalBody = this.normalizeChemicalBody(trimmed);
            return {
                shouldWrap: true,
                mathBody: needsCeWrap ? `\\ce{${chemicalBody}}` : chemicalBody
            };
        }

        return { shouldWrap: false, mathBody: trimmed };
    }

    isAsciiMathContent(text) {
        if (!text) return false;
        const asciiMathPattern = /^[A-Za-z0-9\\^_{}+\-*/().,:;= ]+$/u;
        return asciiMathPattern.test(text);
    }

    isLikelyShortMathToken(text) {
        if (!text) return false;
        const trimmed = text.trim();
        if (trimmed.length === 0 || trimmed.length > 2) return false;

        if (/^[A-Za-z0-9]$/u.test(trimmed) || /^[A-Za-z0-9][0-9]$/u.test(trimmed)) {
            return true;
        }

        const normalized = trimmed.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
        if (normalized.length === 1 && /^[A-Za-z]$/u.test(normalized)) {
            return true;
        }

        if (/^[\u2070-\u209F]$/u.test(trimmed)) {
            return true;
        }

        return false;
    }

    normalizeMathBody(body) {
        if (!body) return body;

        let result = body;

        const accentTransforms = [
            { regex: /([A-Za-z0-9])\u0302/gu, replacement: '\\hat{$1}' },
            { regex: /([A-Za-z0-9])\u0303/gu, replacement: '\\tilde{$1}' },
            { regex: /([A-Za-z0-9])\u0304/gu, replacement: '\\bar{$1}' },
            { regex: /([A-Za-z0-9])\u0307/gu, replacement: '\\dot{$1}' },
            { regex: /([A-Za-z0-9])\u0308/gu, replacement: '\\ddot{$1}' },
            { regex: /([A-Za-z0-9])\u20d7/gu, replacement: '\\vec{$1}' }
        ];
        accentTransforms.forEach(({ regex, replacement }) => {
            result = result.replace(regex, replacement);
        });

        const greekMap = {
            'π': '\\pi ',
            'Π': '\\Pi ',
            'θ': '\\theta ',
            'Θ': '\\Theta ',
            'λ': '\\lambda ',
            'Λ': '\\Lambda ',
            'σ': '\\sigma ',
            'Σ': '\\Sigma ',
            'μ': '\\mu ',
            'µ': '\\mu ',
            'φ': '\\phi ',
            'Φ': '\\Phi ',
            'ω': '\\omega ',
            'Ω': '\\Omega ',
            'α': '\\alpha ',
            'β': '\\beta ',
            'γ': '\\gamma ',
            'Γ': '\\Gamma ',
            'δ': '\\delta ',
            'Δ': '\\Delta ',
            'η': '\\eta ',
            'ρ': '\\rho ',
            'χ': '\\chi ',
            'ζ': '\\zeta ',
            'ξ': '\\xi ',
            'ν': '\\nu ',
            'τ': '\\tau ',
            'ψ': '\\psi ',
            'Ψ': '\\Psi ',
            'κ': '\\kappa '
        };
        result = result.replace(/[\u03B1-\u03C9\u0391-\u03A9\u00B5]/gu, ch => greekMap[ch] || ch);

        const subscriptDigits = {
            '₀': '0', '₁': '1', '₂': '2', '₃': '3', '₄': '4',
            '₅': '5', '₆': '6', '₇': '7', '₈': '8', '₉': '9'
        };
        result = result.replace(/([\u2080-\u2089]+)/gu, match => `_{${[...match].map(ch => subscriptDigits[ch] || '').join('')}}`);

        const superscriptDigits = {
            '⁰': '0', '¹': '1', '²': '2', '³': '3', '⁴': '4',
            '⁵': '5', '⁶': '6', '⁷': '7', '⁸': '8', '⁹': '9',
            '⁺': '+', '⁻': '-', '⁼': '=', '⁽': '(', '⁾': ')'
        };
        result = result.replace(/([\u2070-\u2079\u207A-\u207E]+)/gu, match => `^{${[...match].map(ch => superscriptDigits[ch] || '').join('')}}`);

        result = result.replace(/[\u00B7\u22C5\u2022]/gu, ' \\cdot ');
        result = result.replace(/×/gu, ' \\times ');
        result = result.replace(/÷/gu, ' \\div ');

        result = result.replace(/\s{2,}/g, ' ');

        const slashCount = (result.match(/\//g) || []).length;
        if (slashCount === 1) {
            const fractionMatch = result.match(/^\s*([^/]+?)\s*\/\s*([^/]+?)\s*$/u);
            if (fractionMatch) {
                const numerator = fractionMatch[1].trim();
                const denominator = fractionMatch[2].trim();
                if (numerator && denominator) {
                    result = `\\frac{${numerator}}{${denominator}}`;
                }
            }
        }

        return result.trim();
    }

    normalizeChemicalBody(body) {
        if (!body) return body;
        return body.replace(/[\u00B7\u22C5\u2022]/gu, '\\cdot ');
    }

    looksLikeChemicalEquation(text) {
        if (!text) return false;
        if (text.length < 3) return false;

        const arrowPattern = /(<?[-=]+>|⇌|⇄|↔|→|←|⟶|⟵|⟷|⇆|⇋|⇅)/u;
        const hasConnector = arrowPattern.test(text) || text.includes('+') || /(^|[^A-Za-z])=[^=]/u.test(text);
        if (!hasConnector) return false;

        const compoundPattern = /\b[A-Z][a-z]?(?:\d+(?:\.\d+)?)?(?:_\{[0-9+\-]+\}|_\d+)?(?:\([a-z]{1,3}\))?/gu;
        let compoundCount = 0;
        let match;
        while ((match = compoundPattern.exec(text)) !== null) {
            const fragment = match[0];
            if (!fragment) continue;
            compoundCount++;
            if (compoundCount >= 2) break;
        }

        if (compoundCount < 2) {
            return false;
        }

        const disqualifierPattern = /[`$]/u;
        if (disqualifierPattern.test(text)) return false;

        return true;
    }

    inlineRegex() {
        return new RegExp(this.inlinePatternSource, 'gu');
    }

    commandRegex() {
        return new RegExp(`\\${MathRenderer.COMMAND_PATTERN}`, 'u');
    }

    normalizeDelimited(texWithDelimiters) {
        try {
            let body = texWithDelimiters;
            let start = '', end = '';
            if (texWithDelimiters.startsWith('$$') && texWithDelimiters.endsWith('$$')) {
                start = '$$'; end = '$$';
                body = texWithDelimiters.slice(2, -2);
            } else if (texWithDelimiters.startsWith('$') && texWithDelimiters.endsWith('$')) {
                start = '$'; end = '$';
                body = texWithDelimiters.slice(1, -1);
            } else {
                return texWithDelimiters;
            }

            let normalized = body
                .replace(/\u2208\s*\/\s*/g, '\\notin ')
                .replace(/\u2208\u0338/g, '\\notin ')
                .replace(/\u2209/g, '\\notin ')
                .replace(/\u2282\s*\/\s*/g, '\\not\\subset ')
                .replace(/\u2282\u0338/g, '\\not\\subset ')
                .replace(/\u2286\s*\/\s*/g, '\\not\\subseteq ')
                .replace(/\u2286\u0338/g, '\\not\\subseteq ')
                .replace(/\u2283\s*\/\s*/g, '\\not\\supset ')
                .replace(/\u2283\u0338/g, '\\not\\supset ')
                .replace(/\u2287\s*\/\s*/g, '\\not\\supseteq ')
                .replace(/\u2287\u0338/g, '\\not\\supseteq ')
                .replace(/\u220B\s*\/\s*/g, '\\not\\ni ')
                .replace(/\u220B\u0338/g, '\\not\\ni ')
                .replace(/\u00AC\s*(\w)/g, '\\neg \\! $1')
                .replace(/([A-Za-z])\^(\d{1,2})(?=\d[spdfg])/gi, ($0, base, exp) => `${base}^{${exp}} `)
                .replace(/_([A-Za-z0-9]+)/g, '_{$1}')
                .replace(/\^([A-Za-z]|\d+)/g, '^{$1}')
                .replace(/\text\{([^{}]*?)_(\{[^{}]*\}|[A-Za-z0-9]+?)(\^(\{[^{}]*\}|[A-Za-z0-9]+))?\}/g, (full, base, rawSub, supGroup, rawSup) => {
                    const stripBraces = value => {
                        if (!value) return '';
                        const trimmed = value.trim();
                        if (trimmed.startsWith('{') && trimmed.endsWith('}')) {
                            return trimmed.slice(1, -1);
                        }
                        return trimmed;
                    };
                    const wrapIfText = value => {
                        const trimmed = value.trim();
                        if (!trimmed) return '';
                        if (trimmed.startsWith('\\')) {
                            return trimmed;
                        }
                        if (/^[0-9+\-*/().]+$/.test(trimmed)) {
                            return trimmed;
                        }
                        if (/^[A-Za-z]$/.test(trimmed)) {
                            return trimmed;
                        }
                        return `\\text{${trimmed}}`;
                    };

                    const baseText = base.trim().replace(/\s+/g, ' ');
                    const subContent = stripBraces(rawSub);
                    const supContent = stripBraces(rawSup || '');
                    let rebuilt = `\\text{${baseText}}`;

                    if (subContent) {
                        rebuilt += `_{${wrapIfText(subContent)}}`;
                    }
                    if (supContent) {
                        rebuilt += `^{${wrapIfText(supContent)}}`;
                    }
                    return rebuilt;
                });

            return start + normalized + end;
        } catch (e) {
            return texWithDelimiters;
        }
    }

    static containsMath(text) {
        if (!text) return false;
        return text.includes('$') ||
            text.includes('\\(') ||
            text.includes('\\[') ||
            /\\begin\s*\{[A-Za-z0-9*]+\}/u.test(text);
    }

    renderMath(element, { isFinalRender } = {}) {
        if (!window.renderMathInElement) {
            return;
        }

        try {
            if (element?.dataset?.plainText === 'true') {
                return;
            }
            const textContent = element.textContent;
            const hasMath = MathRenderer.containsMath(textContent);

            if (!hasMath) {
                return;
            }

            const hasRendered = element.querySelector('.katex') !== null;

            if (isFinalRender || !hasRendered) {
                if (!hasRendered) {
                    renderMathInElement(element, this.katexConfig);
                } else {
                    const textNodes = [];
                    const walk = document.createTreeWalker(element, NodeFilter.SHOW_TEXT, null);
                    let node;
                    while ((node = walk.nextNode())) {
                        if (MathRenderer.containsMath(node.textContent || '')) {
                            textNodes.push(node);
                        }
                    }

                    textNodes.forEach(node => {
                        try {
                            const span = document.createElement('span');
                            span.textContent = node.textContent;
                            node.parentNode.insertBefore(span, node);
                            node.parentNode.removeChild(node);
                            renderMathInElement(span, this.partialConfig);
                        } catch (_) { }
                    });
                }
            } else {
                const textNodes = [];
                const walk = document.createTreeWalker(element, NodeFilter.SHOW_TEXT, null);
                let node;
                while ((node = walk.nextNode())) {
                    if (MathRenderer.containsMath(node.textContent || '')) {
                        textNodes.push(node);
                    }
                }

                textNodes.forEach(node => {
                    try {
                        const span = document.createElement('span');
                        span.textContent = node.textContent;
                        node.parentNode.insertBefore(span, node);
                        node.parentNode.removeChild(node);
                        renderMathInElement(span, this.partialConfig);
                    } catch (_) { }
                });
            }
        } catch (_) { }
    }

    renderElement(element, isFinalRender = false) {
        this.renderMath(element, { isFinalRender: !!isFinalRender });
    }
}

const mathRenderer = new MathRenderer(KATEX_CONFIG);
if (typeof window !== 'undefined') {
    window.mathRenderer = mathRenderer;
}
const STREAMING_HORIZONTAL_RULE_TAIL_RE = /(?:^|\r?\n)[ \t]{0,3}([\*\-_])(?:[ \t]*\1){2,}[ \t]*$/;
const EXPLICIT_HORIZONTAL_RULE_RE = /(?:^|\r?\n)[ \t]{0,3}([*\-_])(?:[ \t]*\1){2,}[ \t]*(?:\r?\n|$)/;

function findLastCompleteDisplayMathEnd(html) {
    if (!html) return -1;
    const indices = [];
    for (let i = 0; i < html.length - 1; i++) {
        if (html[i] === '$' && html[i + 1] === '$' && html[i - 1] !== '\\') {
            indices.push(i);
        }
    }
    if (indices.length < 2) return -1;
    if (indices.length % 2 === 1) indices.pop();

    const closingIndex = indices[indices.length - 1];
    let end = closingIndex + 2;
    const tail = html.slice(end).match(/^(?:\s*(?:<\/p>|<\/div>|<br\s*\/?>))+/i);
    if (tail) end += tail[0].length;
    return end;
}

function stripStreamingHorizontalRuleTail(text) {
    if (!text) return text;
    let end = text.length;
    while (end > 0) {
        const code = text.charCodeAt(end - 1);
        if (code === 10 || code === 13) {
            end--;
        } else {
            break;
        }
    }
    const withoutTrailingNewlines = text.slice(0, end);
    const match = withoutTrailingNewlines.match(STREAMING_HORIZONTAL_RULE_TAIL_RE);
    if (!match) {
        return text;
    }
    const removalStart = withoutTrailingNewlines.length - match[0].length;
    const trimmed = withoutTrailingNewlines.slice(0, removalStart);
    return trimmed + text.slice(end);
}

let cidHydrationScheduled = false;
const CID_IMAGE_CACHE = new Map();

function scheduleCidImageHydration(element) {
    if (!element || cidHydrationScheduled) return;
    cidHydrationScheduled = true;
    requestAnimationFrame(() => {
        cidHydrationScheduled = false;
        hydrateCidImages(element).catch(() => { });
    });
}

async function hydrateCidImages(container) {
    const imgs = Array.from(container.querySelectorAll('img[data-cid]'));
    if (imgs.length === 0) return;
    for (const img of imgs) {
        const hash = img.dataset.cid;
        if (!hash || img.dataset.cidLoaded === '1') continue;
        img.dataset.cidLoaded = '1';
        try {
            let url = CID_IMAGE_CACHE.get(hash);
            if (!url) {
                const blob = await LocalStore.getImage(hash, currentChatId);
                if (!blob) continue;
                url = URL.createObjectURL(blob);
                CID_IMAGE_CACHE.set(hash, url);
            }
            try {
                const meta = await LocalStore.getMeta(hash);
                if (meta?.width && meta?.height) {
                    img.width = meta.width;
                    img.height = meta.height;
                    const maxSide = Math.max(meta.width, meta.height);
                    if (maxSide > 300) {
                        img.classList.add('cid-image-large');
                    }
                }
            } catch (_) { }
            img.src = url;
            img.style.maxWidth = '100%';
            img.style.height = 'auto';
            img.style.verticalAlign = 'middle';
        } catch (_) {
            // Ignore missing images.
        }
    }
}

function renderMessageContent(element, content, citations = null, isFinalRender = false, options = {}) {
    if (!isFinalRender) {
        const throttleState = element.__renderThrottle || (element.__renderThrottle = {
            pending: false,
            latestArgs: null
        });

        if (throttleState.pending) {
            throttleState.latestArgs = { content, citations, options };
            return null;
        }

        throttleState.pending = true;
        throttleState.latestArgs = null;

        requestAnimationFrame(() => {
            throttleState.pending = false;
            if (throttleState.latestArgs) {
                const args = throttleState.latestArgs;
                throttleState.latestArgs = null;
                renderMessageContent(element, args.content, args.citations, false, args.options);
            }
        });
    } else {
        delete element.__renderThrottle;
    }

    const isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
    const { forcePlainText = false } = options || {};
    let renderTimeout;

    const clearRenderState = () => {
        if (element.__renderState) {
            delete element.__renderState;
        }
    };

    if (isMobile) {
        renderTimeout = setTimeout(() => {
            console.warn(getToastMessage('console.mobileRenderTimeout'));
            if (typeof content === 'string' && content.includes('<table')) {
                const simplifiedContent = content.replace(/<table[^>]*>[\s\S]*?<\/table>/gi, `[${getToastMessage('ui.tableTooLarge')}]`);
                element.innerHTML = DOMPurify.sanitize(simplifiedContent);
            }
        }, 2000); // 2秒超时
    }

    if (Array.isArray(content)) {
        element.innerHTML = '';
        clearRenderState();
        content.forEach(part => {
            if (part.type === 'quote') {
                const quoteDiv = document.createElement('div');
                quoteDiv.style.cssText = "background-color: rgba(0, 0, 0, 0.05); border-left: 3px solid rgba(0, 0, 0, 0.2); padding: 8px 12px; margin-bottom: 8px; border-radius: 4px; font-size: 0.9em; color: #555; white-space: pre-wrap; word-break: break-word;";
                const truncatedText = part.text.length > 150 ? part.text.substring(0, 150) + '...' : part.text;
                quoteDiv.textContent = truncatedText;
                element.appendChild(quoteDiv);
            } else if (part.type === 'text') {
                const textDiv = document.createElement('div');
                textDiv.style.whiteSpace = 'pre-wrap';
                textDiv.textContent = part.text;
                element.appendChild(textDiv);
            } else if (part.type === 'image_url') {
                if (part._hidden) {
                    return;
                }
                const img = document.createElement('img');
                img.src = part.image_url.url;
                img.className = 'preview';
                img.style.maxWidth = '200px';
                img.style.borderRadius = '8px';
                element.appendChild(img);
            } else if (part.type === 'file') {
                const fileChip = document.createElement('div');
                fileChip.className = 'file-chip-display';
                const fileIcon = document.createElement('svg');
                fileIcon.setAttribute('viewBox', '0 0 24 24');
                const filePath = document.createElement('path');
                filePath.setAttribute('d', 'M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z');
                fileIcon.appendChild(filePath);

                const fileName = document.createElement('span');
                fileName.className = 'file-name';
                fileName.textContent = part.filename || '';

                fileChip.appendChild(fileIcon);
                fileChip.appendChild(fileName);
                fileChip.dataset.filename = part.filename;
                fileChip.addEventListener('click', () => {
                    showFileViewer(part.filename, part.content, part);
                });
                element.appendChild(fileChip);
            }
        });

        if (renderTimeout) {
            clearTimeout(renderTimeout);
        }
        return null;
    }

    let messageText = '';
    let localCitations = citations;
    let streamImageParts = [];
    let streamImageLayout = [];

    if (typeof content === 'object' && content !== null && 'content' in content) {
        messageText = content.content;
        streamImageParts = streamImageRuntime.normalizeStreamImageParts(content.image_parts || content.image_urls || []);
        streamImageLayout = streamImageRuntime.normalizeStreamImageLayout(content.image_layout || []);
        if (content.citations) {
            localCitations = content.citations;
        }
    } else if (typeof content === 'string') {
        messageText = content;
    } else {
        element.textContent = String(content);
        if (renderTimeout) {
            clearTimeout(renderTimeout);
        }
        clearRenderState();
        return null;
    }

    messageText = rewritePexelsAttributionInMarkdown(messageText);

    if (forcePlainText) {
        try { element.dataset.plainText = 'true'; } catch (_) { }
        try { element.dataset.rawText = messageText || ''; } catch (_) { }
        element.textContent = messageText || '';
        element.style.whiteSpace = 'pre-wrap';
        if (renderTimeout) {
            clearTimeout(renderTimeout);
        }
        clearRenderState();
        return null;
    }

    try {
        try { element.dataset.rawText = messageText || ''; } catch (_) { }
        const resourcesReady = window.marked && window.DOMPurify && window.hljs && window.renderMathInElement;
        if (!resourcesReady) {
            if (!window.renderMathInElement && typeof loadScript === 'function' && !element.__mathScriptLoading && !element.__mathScriptAttempted) {
                element.__mathScriptLoading = true;
                element.__mathScriptAttempted = true;
                Promise.resolve()
                    .then(() => loadScript('/libs/katex.min.js', 'katex'))
                    .then(() => loadScript('/libs/auto-render.min.js', 'renderMathInElement'))
                    .catch(() => { })
                    .finally(() => {
                        element.__mathScriptLoading = false;
                        renderMessageContent(element, content, citations, isFinalRender);
                    });
            }
            element.textContent = messageText;
            if (renderTimeout) clearTimeout(renderTimeout);
            clearRenderState();
            return null;
        }

        const unwrapNestedDiagramFences = (text) => {
            const fenceRe = /(```|~~~)(?:markdown|md|text|plain)?[^\r\n]*\r?\n([\s\S]*?)(\1)/gi;
            return text.replace(fenceRe, (m, fence, inner) => {
                const diagRe = /(```|~~~)\s*(mermaid|vega(?:-lite)?|vega-lite)[^\r\n]*\r?\n([\s\S]*?)(\1)/i;
                const diagMatch = inner.match(diagRe);
                if (!diagMatch) return m;
                const opening = diagMatch[1];
                const lang = diagMatch[2] || '';
                const body = diagMatch[3] || '';
                return `${opening}${lang}\n${body}${opening}`;
            });
        };

        let correctedContent = unwrapNestedDiagramFences(mathRenderer.preprocessMarkdown(messageText));
        const displayMath = [];
        const inlineMath = [];

        let protectedContent = correctedContent.replace(/\$\$([\s\S]*?)\$\$/g, (match) => {
            displayMath.push(mathRenderer.normalizeDelimited(match));
            return `%%DISPLAY_MATH_${displayMath.length - 1}%%`;
        });

        protectedContent = protectedContent.replace(/\$([^$\n]+?)\$/g, (match) => {
            inlineMath.push(mathRenderer.normalizeDelimited(match));
            return `%%INLINE_MATH_${inlineMath.length - 1}%%`;
        });

        let contentToParse = protectedContent;
        let syntheticFenceAdded = false;

        if (!isFinalRender) {
            const lines = protectedContent.split(/\r?\n/);
            let openFence = null;
            for (const line of lines) {
                const m = line.match(/^\s{0,3}([`~]{3,})(.*)$/);
                if (!m) continue;
                const fenceChars = m[1];
                const ch = fenceChars[0];
                const len = fenceChars.length;
                if (!openFence) {
                    openFence = { ch, len };
                } else if (ch === openFence.ch && len >= openFence.len) {
                    openFence = null;
                }
            }

            if (openFence) {
                const tailPartialRe = new RegExp(`(?:\\r?\\n)?\\s*${openFence.ch === '`' ? "\\`" : "~"}{1,2}\\s*$`);
                contentToParse = protectedContent.replace(tailPartialRe, '');

                const fenceLine = (contentToParse.endsWith('\n') ? '' : '\n') + openFence.ch.repeat(openFence.len);
                contentToParse = contentToParse + fenceLine;
                syntheticFenceAdded = true;
            }

            if (!syntheticFenceAdded) {
                contentToParse = stripStreamingHorizontalRuleTail(contentToParse);
            }
        }

        const containsExplicitHorizontalRule = EXPLICIT_HORIZONTAL_RULE_RE.test(contentToParse) || /<\s*hr\b/i.test(contentToParse);

        const previousScrollState = {
            codeBlocks: Array.from(element.querySelectorAll('pre')).map(block => ({
                scrollLeft: block.scrollLeft,
                scrollTop: block.scrollTop
            })),
            tables: Array.from(element.querySelectorAll('.table-wrapper')).map(wrapper => ({
                scrollLeft: wrapper.scrollLeft,
                scrollTop: wrapper.scrollTop
            }))
        };

        // 性能优化
        const parseState = element.__parseState || (element.__parseState = {
            lastContentToParse: '',
            lastParsedHtml: ''
        });

        if (!isFinalRender && parseState.lastContentToParse === contentToParse) {
            if (renderTimeout) clearTimeout(renderTimeout);
            return null;
        }

        let html = marked.parse(contentToParse);

        // 更新缓存
        if (!isFinalRender) {
            parseState.lastContentToParse = contentToParse;
            parseState.lastParsedHtml = html;
        } else {
            delete element.__parseState;
        }

        let hasCitationList = false;
        const sourcesMap = new Map();
        if (localCitations && localCitations.length > 0) {
            localCitations.forEach((citation, index) => {
                sourcesMap.set(index + 1, citation);
            });
        }
        const citationRegex = /([（(]?)\s*\[([\d, ]+)\]\s*([）)])?/g;
        let citedHtml = html.replace(citationRegex, (match, openParen, numbersStr, closeParen) => {
            const numbers = numbersStr.split(',').map(s => parseInt(s.trim(), 10));
            const links = numbers.map(number => {
                if (isNaN(number)) return '';
                const source = sourcesMap.get(number);
                return source && source.uri ? `<a href="${source.uri}" target="_blank" title="${source.title || ''}" class="citation-link">[${number}]</a>` : `[${number}]`;
            }).join('');

            if (!links) {
                return match;
            }
            if (openParen && closeParen) {
                return links;
            }
            if (openParen && !closeParen) {
                return openParen + links;
            }
            if (!openParen && closeParen) {
                return links + closeParen;
            }
            return links;
        });
        if (sourcesMap.size > 0) {
            let sourcesListHtml = `<div class="sources-list-container"><h4>${getToastMessage('ui.references')}：</h4><ul>`;
            sourcesMap.forEach((source, number) => {
                sourcesListHtml += `<li><span class="source-number">[${number}]</span> <a href="${source.uri}" target="_blank" title="${source.uri}">${source.title || source.uri}</a></li>`;
            });
            sourcesListHtml += '</ul></div>';
            citedHtml += sourcesListHtml;
            hasCitationList = true;
        }
        html = citedHtml;

        html = html.replace(/%%DISPLAY_MATH_(\d+)%%/g, (match, index) => displayMath[parseInt(index, 10)]);
        html = html.replace(/%%INLINE_MATH_(\d+)%%/g, (match, index) => inlineMath[parseInt(index, 10)]);

        const sanitizedHtml = DOMPurify.sanitize(html, {
            ADD_TAGS: ['div', 'table', 'thead', 'tbody', 'tr', 'th', 'td', 'span', 'img', 'br', 'a', 'h4', 'ul', 'li'],
            ADD_ATTR: ['style', 'class', 'aria-hidden', 'src', 'alt', 'title', 'href', 'target', 'rel', 'data-cid', 'data-stream-image-slot']
        });

        const tempContainer = document.createElement('div');
        tempContainer.innerHTML = sanitizedHtml;
        if (!containsExplicitHorizontalRule) {
            try {
                tempContainer.querySelectorAll('hr').forEach(hr => hr.remove());
            } catch (_) { }
        }

        tempContainer.querySelectorAll('table').forEach(table => {
            const rows = table.querySelectorAll('tr');
            if (rows.length > MAX_TABLE_ROWS) {
                const tbody = table.querySelector('tbody');
                if (tbody) {
                    const originalRows = Array.from(tbody.querySelectorAll('tr'));
                    tbody.innerHTML = '';
                    originalRows.slice(0, MAX_TABLE_ROWS).forEach(row => tbody.appendChild(row));
                }

                const warningDiv = document.createElement('div');
                warningDiv.textContent = getToastMessage('status.tableTruncated', { maxRows: MAX_TABLE_ROWS, totalRows: rows.length });
                warningDiv.style.cssText = "color: #ff9800; font-size: 12px; margin-top: 8px; text-align: center; padding: 4px; background-color: #fffbe6; border: 1px solid #ffe58f; border-radius: 4px;";

                if (table.parentElement && table.parentElement.classList.contains('table-wrapper')) {
                    table.parentElement.insertAdjacentElement('afterend', warningDiv);
                } else {
                    table.insertAdjacentElement('afterend', warningDiv);
                }
            }
        });

        try {
            tempContainer.querySelectorAll('pre code').forEach(codeEl => {
                const original = codeEl.textContent || '';
                if (!original) return;
                const lines = original.split(/\r?\n/);
                while (lines.length && lines[lines.length - 1].trim() === '') lines.pop();
                let changed = false;
                while (lines.length && /^[`~]{1,2}$/.test(lines[lines.length - 1].trim())) { lines.pop(); changed = true; }
                if (lines.length && /^>$/.test(lines[lines.length - 1].trim())) { lines.pop(); changed = true; }
                if (changed) {
                    codeEl.textContent = lines.join('\n');
                }
            });
        } catch (_) { }

        try {
            const removePatterns = [/^\s*>\s*$/, /^\s*\]>\s*$/, /^\s*\|>\s*$/];
            const walker = document.createTreeWalker(tempContainer, NodeFilter.SHOW_TEXT, null, false);
            const toRemove = [];
            let n;
            while ((n = walker.nextNode())) {
                const parentTag = (n.parentNode && n.parentNode.tagName) ? n.parentNode.tagName.toUpperCase() : '';
                if (parentTag === 'CODE' || parentTag === 'PRE' || parentTag === 'BLOCKQUOTE' || parentTag === 'A') continue;
                const txt = (n.textContent || '').trim();
                if (!txt) continue;
                if (removePatterns.some(re => re.test(txt))) {
                    toRemove.push(n);
                }
            }
            toRemove.forEach(node => node.parentNode && node.parentNode.removeChild(node));
        } catch (_) { }

        try {
            const preBlocks = tempContainer.querySelectorAll('pre');
            if (preBlocks.length > 0) {
                const lastPre = preBlocks[preBlocks.length - 1];
                if (lastPre && !lastPre.nextElementSibling) {
                    const codeEl = lastPre.querySelector('code');
                    const codeText = codeEl ? (codeEl.textContent || '').trim() : '';
                    if (!isFinalRender && codeText.length === 0) {
                        lastPre.parentNode.removeChild(lastPre);
                    }
                }
            }
        } catch (_) { }

        try {
            tempContainer.querySelectorAll('img').forEach(img => {
                const src = img.getAttribute('src') || '';
                if (src.startsWith('cid:')) {
                    img.setAttribute('data-cid', src.slice(4));
                    img.setAttribute('src', '');
                    img.classList.add('cid-image-placeholder');
                }
            });
        } catch (_) { }

        const finalSanitizedHtml = tempContainer.innerHTML;
        const renderState = element.__renderState || (element.__renderState = {
            lockedLength: 0,
            lockedHtml: '',
            lastLockedHtml: '',
            streamingHtml: '',
            lockedContainer: null,
            streamingContainer: null
        });

        const lowerHtml = finalSanitizedHtml.toLowerCase();
        const lastTableCloseIndex = lowerHtml.lastIndexOf('</table>');
        const lastPreCloseIndex = lowerHtml.lastIndexOf('</pre>');
        const tableLockEnd = lastTableCloseIndex === -1 ? -1 : lastTableCloseIndex + '</table>'.length;
        const codeLockEnd = lastPreCloseIndex === -1 ? -1 : lastPreCloseIndex + '</pre>'.length;

        let mathLockEnd = findLastCompleteDisplayMathEnd(finalSanitizedHtml);

        const newLockEnd = syntheticFenceAdded
            ? Math.max(tableLockEnd, mathLockEnd)
            : Math.max(tableLockEnd, codeLockEnd, mathLockEnd);

        if (newLockEnd > renderState.lockedLength) {
            renderState.lockedLength = newLockEnd;
            renderState.lockedHtml = finalSanitizedHtml.slice(0, newLockEnd);
        }

        let streamingHtml = finalSanitizedHtml.slice(renderState.lockedLength);

        if (!isFinalRender && streamingHtml) {
            const tempDiv = document.createElement('div');
            tempDiv.innerHTML = streamingHtml;

            const walker = document.createTreeWalker(tempDiv, NodeFilter.SHOW_TEXT, null, false);
            let targetNode = null;
            while (true) {
                const n = walker.nextNode();
                if (!n) break;
                const parentTag = (n.parentNode && n.parentNode.tagName) ? n.parentNode.tagName.toUpperCase() : '';
                if (parentTag !== 'CODE' && parentTag !== 'PRE' && parentTag !== 'BLOCKQUOTE') {
                    targetNode = n;
                    break;
                }
            }

            if (targetNode && targetNode.textContent) {
                const before = targetNode.textContent;
                const after = before
                    .replace(/^\s*>(\s+)?/, '')
                    .replace(/^\s*([`~]{3,})\s*$/, '')
                    .replace(/^\s*([`~]{1,2})\s*$/, '')
                    .replace(/^\s*\]\>\s*/, '')
                    .replace(/^\s*\|\>\s*/, '')
                    .replace(/^\s*\]>\s*/, '');
                if (after !== before) {
                    targetNode.textContent = after;
                    streamingHtml = tempDiv.innerHTML;
                }
            }
        }

        if (!renderState.lockedContainer || !renderState.streamingContainer || !element.contains(renderState.lockedContainer)) {
            const preservedStreamImageNodes = Array.from(element.querySelectorAll('.stream-image-attachments'));
            element.innerHTML = '';
            renderState.lockedContainer = document.createElement('div');
            renderState.lockedContainer.className = 'locked-response-content';
            renderState.lockedContainer.style.display = 'contents';
            renderState.streamingContainer = document.createElement('div');
            renderState.streamingContainer.className = 'streaming-response-content';
            renderState.streamingContainer.style.display = 'contents';
            element.appendChild(renderState.lockedContainer);
            element.appendChild(renderState.streamingContainer);
            preservedStreamImageNodes.forEach((node) => element.appendChild(node));
            renderState.lastLockedHtml = '';
            renderState.streamingHtml = '';
        }

        const isNodeImmediatelyAfter = (node, target) => {
            if (!node || !target || !target.parentNode) return false;
            if (node.parentNode !== target.parentNode) return false;
            let cursor = target.nextSibling;
            while (cursor && cursor.nodeType === Node.TEXT_NODE && !String(cursor.textContent || '').trim()) {
                cursor = cursor.nextSibling;
            }
            return cursor === node;
        };

        const repositionPendingNode = (node) => {
            if (!node || !node.isConnected) return;
            if (!isFinalRender && scrollManager.isUserScrolling) return;

            let placement = '';
            const pendingSlot = String(node.dataset.pendingSlot || '').trim();
            if (pendingSlot) {
                placement = `slot:${pendingSlot}`;
            } else {
                const pendingKey = String(node.dataset.pendingKey || '').trim();
                if (pendingKey) {
                    const first = pendingKey.indexOf(':');
                    const second = first >= 0 ? pendingKey.indexOf(':', first + 1) : -1;
                    if (second >= 0 && second < pendingKey.length - 1) {
                        placement = pendingKey.slice(second + 1).trim();
                    }
                }
            }
            if (!placement) return;

            const normalizedPlacement = streamImageRuntime.normalizeStreamImagePlacement(placement);
            if (normalizedPlacement.startsWith('slot:')) {
                const slotId = normalizedPlacement.slice('slot:'.length).trim();
                const anchor = slotId ? element.querySelector(`[data-stream-image-slot="${slotId}"]`) : null;
                if (!anchor) return;
                const anchorBlock = anchor.closest('p, li, blockquote, pre, table, h1, h2, h3, h4, h5, h6');
                const target = (anchorBlock && anchorBlock.parentNode) ? anchorBlock : (anchor.parentNode ? anchor : null);
                if (!target) return;
                if (isNodeImmediatelyAfter(node, target)) return;
                if (target === anchorBlock) {
                    anchorBlock.insertAdjacentElement('afterend', node);
                } else {
                    anchor.insertAdjacentElement('afterend', node);
                }
                return;
            }

            if (normalizedPlacement.startsWith('after_paragraph:')) {
                const n = Math.max(1, parseInt(normalizedPlacement.split(':')[1], 10) || 1);
                const paragraphTargets = Array.from(
                    element.querySelectorAll('p, li, blockquote, pre, table, h1, h2, h3, h4, h5, h6')
                ).filter(target => !target.closest('.stream-image-attachments'));
                const target = paragraphTargets[Math.min(n - 1, paragraphTargets.length - 1)];
                if (target && target.parentNode) {
                    if (isNodeImmediatelyAfter(node, target)) return;
                    target.insertAdjacentElement('afterend', node);
                }
                return;
            }

            if (normalizedPlacement === 'head') {
                const firstNode = element.firstElementChild;
                if (firstNode && firstNode !== node) {
                    element.insertBefore(node, firstNode);
                }
            }
        };

        if (renderState.lastLockedHtml !== renderState.lockedHtml) {
            let contentChanged = false;
            if (renderState.lockedHtml.startsWith(renderState.lastLockedHtml)) {
                const delta = renderState.lockedHtml.slice(renderState.lastLockedHtml.length);
                if (delta) {
                    renderState.lockedContainer.insertAdjacentHTML('beforeend', delta);
                    contentChanged = true;
                }
            } else {
                renderState.lockedContainer.innerHTML = renderState.lockedHtml;
                contentChanged = true;
            }
            renderState.lastLockedHtml = renderState.lockedHtml;
        }

        if (renderState.streamingHtml !== streamingHtml) {
            let contentChanged = false;
            if (streamingHtml.startsWith(renderState.streamingHtml)) {
                const delta = streamingHtml.slice(renderState.streamingHtml.length);
                if (delta) {
                    renderState.streamingContainer.insertAdjacentHTML('beforeend', delta);
                    contentChanged = true;
                }
            } else {
                renderState.streamingContainer.innerHTML = streamingHtml;
                contentChanged = true;
            }
            renderState.streamingHtml = streamingHtml;
        }

        Array.from(element.querySelectorAll('.stream-image-attachments[data-pending="1"]')).forEach(repositionPendingNode);

        let reasoningText = '';
        if (typeof content === 'object' && content !== null && typeof content.reasoning === 'string') {
            reasoningText = content.reasoning;
        } else if (options && typeof options.reasoning === 'string') {
            reasoningText = options.reasoning;
        }

        const reasoningValue = (typeof reasoningText === 'string') ? reasoningText.trim() : '';
        const existingReasoning = element.querySelector('.reasoning-toggle');
        if (reasoningValue) {
            let reasoningBlock = existingReasoning;
            if (!reasoningBlock) {
                reasoningBlock = document.createElement('details');
                reasoningBlock.className = 'reasoning-toggle';
                const summaryEl = document.createElement('summary');
                summaryEl.className = 'reasoning-summary';
                summaryEl.innerHTML = `
                    <span class="reasoning-icon" aria-hidden="true">
                        <svg viewBox="0 0 24 24" fill="currentColor">
                            <path d="M12 2a7 7 0 0 0-4.1 12.7L8 22l4-2 4 2 .1-7.3A7 7 0 0 0 12 2Zm0 2a5 5 0 0 1 3 9l-.5.4.1 5-2.6-1.3-2.6 1.3.1-5-.5-.4A5 5 0 0 1 12 4Zm0 3.2a.9.9 0 0 0-.9.9v2.3l-.9.6a.9.9 0 1 0 1 1.6l1.3-.8a.9.9 0 0 0 .4-.8V8.1a.9.9 0 0 0-.9-.9Z"/>
                        </svg>
                    </span>
                    <span class="reasoning-title">${getToastMessage('ui.thinking')}</span>
                    <span class="reasoning-caret" aria-hidden="true"></span>
                `;
                reasoningBlock.appendChild(summaryEl);
                const bodyEl = document.createElement('div');
                bodyEl.className = 'reasoning-content';
                reasoningBlock.appendChild(bodyEl);
                if (renderState.lockedContainer && element.contains(renderState.lockedContainer)) {
                    element.insertBefore(reasoningBlock, renderState.lockedContainer);
                } else {
                    element.prepend(reasoningBlock);
                }
            }
            const body = reasoningBlock.querySelector('.reasoning-content');
            if (body) {
                body.textContent = reasoningValue;
            }
        } else if (existingReasoning) {
            existingReasoning.remove();
        }

        const pendingAnchorReached = !!(
            typeof messageText === 'string' &&
            (
                messageText.includes(getToastMessage('ui.generatedImageForYou'))
                || messageText.includes('data-stream-image-slot=')
            )
        );
        streamImageRuntime.syncStreamImageAttachments(element, streamImageParts, streamImageLayout, isFinalRender, {
            pendingPlaceholder: !options?.staticImageRender && !!options?.pendingImagePlaceholder,
            staticImageRender: !!options?.staticImageRender,
            pendingAnchorReached
        });

        if (isFinalRender) {
            scheduleCidImageHydration(element);
        }
        const chatContainer = elements?.chatContainer || null;
        const containerRect = chatContainer ? chatContainer.getBoundingClientRect() : null;
        const elementRect = chatContainer ? element.getBoundingClientRect() : null;
        const elementVisibleBefore = !!(containerRect && elementRect &&
            elementRect.bottom > containerRect.top &&
            elementRect.top < containerRect.bottom);
        const canAdjustScroll = !elementVisibleBefore;
        const userInteracting = scrollManager.isUserScrolling || (Date.now() - scrollManager.lastUserScrollAt < 250);
        const applyProgrammaticScrollTop = (targetTop) => {
            if (!chatContainer) return;
            scrollManager.setAutoScrollTop(targetTop);
        };

        const mermaidRenderPromise = renderMermaidDiagramsLazy(element, { loadScript, isFinalRender });
        if (mermaidRenderPromise) {
            element.__mermaidRenderPromise = mermaidRenderPromise;
            // 记录渲染前的高度和滚动位置
            const beforeHeight = chatContainer?.scrollHeight || 0;
            const beforeScrollTop = chatContainer?.scrollTop || 0;
            const beforeUserScrollAt = scrollManager.lastUserScrollAt;
            const beforeShouldAutoScroll = shouldAutoScroll();
            const beforePinnedToBottom = scrollManager.getDistanceToBottom() <= scrollManager.bottomStrictThreshold;
            let elementTopBefore = 0;
            if (containerRect && elementRect) {
                elementTopBefore = elementRect.top - containerRect.top + beforeScrollTop;
            }
            mermaidRenderPromise.catch(() => { }).finally(() => {
                if (!chatContainer) return;
                const afterHeight = chatContainer.scrollHeight;
                const heightDelta = afterHeight - beforeHeight;

                const nowUserInteracting = scrollManager.isUserScrolling ||
                    (Date.now() - scrollManager.lastUserScrollAt < 250);
                const pinnedToBottom = scrollManager.getDistanceToBottom() <= scrollManager.bottomStrictThreshold;

                if (nowUserInteracting && !pinnedToBottom && !beforeShouldAutoScroll && !shouldAutoScroll()) return;
                if (!isFinalRender && (beforeShouldAutoScroll || beforePinnedToBottom || shouldAutoScroll() || pinnedToBottom)) {
                    scrollManager.scheduleSmoothScrollToBottomStable();
                } else if (shouldPreserveScrollPosition() && canAdjustScroll) {
                    const userMoved = scrollManager.lastUserScrollAt !== beforeUserScrollAt ||
                        Math.abs(chatContainer.scrollTop - beforeScrollTop) > 2;
                    if (userMoved) return;
                    if (heightDelta !== 0 &&
                        elementTopBefore < beforeScrollTop &&
                        beforeScrollTop < beforeHeight - chatContainer.clientHeight) {
                        applyProgrammaticScrollTop(beforeScrollTop + heightDelta);
                    }
                }
            });
        }

        const diagramPlaceholders = [];
        if (isFinalRender) {
            element.querySelectorAll('.mermaid-render-container, .vega-lite-render-container').forEach(diagramEl => {
                const h = diagramEl.offsetHeight;
                if (h > 0) {
                    diagramEl.style.minHeight = `${h}px`;
                    diagramPlaceholders.push(diagramEl);
                }
            });
        }

        const vegaRenderPromise = renderVegaLiteDiagramsLazy(element, { loadScript, isFinalRender });
        const cleanupDiagrams = () => {
            diagramPlaceholders.forEach(el => { el.style.minHeight = ''; });
        };
        if (vegaRenderPromise) {
            element.__vegaLiteRenderPromise = vegaRenderPromise;
            // 记录渲染前的高度和滚动位置
            const vegaBeforeHeight = chatContainer?.scrollHeight || 0;
            const vegaBeforeScrollTop = chatContainer?.scrollTop || 0;
            const vegaBeforeUserScrollAt = scrollManager.lastUserScrollAt;
            const vegaBeforeShouldAutoScroll = shouldAutoScroll();
            const vegaBeforePinnedToBottom = scrollManager.getDistanceToBottom() <= scrollManager.bottomStrictThreshold;
            let vegaElementTopBefore = 0;
            if (containerRect && elementRect) {
                vegaElementTopBefore = elementRect.top - containerRect.top + vegaBeforeScrollTop;
            }
            vegaRenderPromise.catch(() => { }).finally(() => {
                const cleanupBeforeHeight = chatContainer?.scrollHeight || 0;
                cleanupDiagrams();
                const cleanupAfterHeight = chatContainer?.scrollHeight || cleanupBeforeHeight;
                const cleanupHeightDelta = cleanupAfterHeight - cleanupBeforeHeight;
                if (!chatContainer) return;
                const afterHeight = chatContainer.scrollHeight;
                const heightDelta = afterHeight - vegaBeforeHeight;

                const nowUserInteracting = scrollManager.isUserScrolling ||
                    (Date.now() - scrollManager.lastUserScrollAt < 250);
                const pinnedToBottom = scrollManager.getDistanceToBottom() <= scrollManager.bottomStrictThreshold;

                if (nowUserInteracting && !pinnedToBottom && !vegaBeforeShouldAutoScroll && !shouldAutoScroll()) return;

                if (!isFinalRender && (vegaBeforeShouldAutoScroll || vegaBeforePinnedToBottom || shouldAutoScroll() || pinnedToBottom)) {
                    scrollManager.scheduleSmoothScrollToBottomStable();
                } else if (shouldPreserveScrollPosition() && canAdjustScroll) {
                    const userMoved = scrollManager.lastUserScrollAt !== vegaBeforeUserScrollAt ||
                        Math.abs(chatContainer.scrollTop - vegaBeforeScrollTop) > 2;
                    if (userMoved) return;
                    if (heightDelta !== 0 &&
                        vegaElementTopBefore < vegaBeforeScrollTop &&
                        vegaBeforeScrollTop < vegaBeforeHeight - chatContainer.clientHeight) {
                        applyProgrammaticScrollTop(vegaBeforeScrollTop + heightDelta);
                    }
                }
            });
        } else {
            const cleanupBeforeHeight = chatContainer?.scrollHeight || 0;
            cleanupDiagrams();
            const cleanupAfterHeight = chatContainer?.scrollHeight || cleanupBeforeHeight;
            const cleanupHeightDelta = cleanupAfterHeight - cleanupBeforeHeight;
            const shouldFollowAfterCleanup = shouldAutoScroll() || (scrollManager.getDistanceToBottom() <= scrollManager.bottomStrictThreshold);
            if (!isFinalRender && chatContainer && shouldFollowAfterCleanup && cleanupHeightDelta !== 0) {
                scrollManager.scheduleSmoothScrollToBottomStable();
            }
        }

        mathRenderer.renderMath(element, { isFinalRender });

        if (window.hljs) {
            ensurePlaintextHighlightLanguage();
            element.querySelectorAll('pre code').forEach(block => {
                const cls = block.className || '';
                const isMermaidLike = cls.includes('language-mermaid');
                const isVegaLike = cls.includes('language-vega-lite') || cls.includes('language-vega');
                if (!isMermaidLike && !isVegaLike) {
                    if (block.dataset.vegaLitePending === 'true') {
                        delete block.dataset.vegaLitePending;
                    }
                    if (block.dataset.mermaidPending === 'true') {
                        delete block.dataset.mermaidPending;
                    }
                }
            });
            const candidateBlocks = Array.from(element.querySelectorAll('pre code'))
                .filter(block => block.dataset.mermaidPending !== 'true' &&
                    block.dataset.mermaidProcessed !== 'true' &&
                    block.dataset.vegaLitePending !== 'true' &&
                    block.dataset.vegaLiteProcessed !== 'true' &&
                    block.closest('.mermaid-render-container') === null &&
                    block.closest('.vega-lite-render-container') === null &&
                    !(block.className || '').includes('language-plaintext') &&
                    !(block.className || '').includes('language-mermaid') &&
                    !(block.className || '').includes('language-vega-lite') &&
                    !(block.className || '').includes('language-vega'));

            if (isFinalRender) {
                const totalCodeBlocks = candidateBlocks.length;
                const highlightedBlocks = candidateBlocks.filter(block => block.classList.contains('hljs')).length;

                if (highlightedBlocks < totalCodeBlocks) {
                    candidateBlocks
                        .filter(block => !block.classList.contains('hljs'))
                        .forEach(block => {
                            try {
                                hljs.highlightElement(block);
                            } catch (e) { }
                        });
                }
            } else {
                element.querySelectorAll('pre code:not(.hljs)').forEach(block => {
                    if (block.dataset.mermaidPending === 'true' ||
                        block.dataset.mermaidProcessed === 'true' ||
                        block.dataset.vegaLitePending === 'true' ||
                        block.dataset.vegaLiteProcessed === 'true' ||
                        block.closest('.mermaid-render-container') ||
                        block.closest('.vega-lite-render-container') ||
                        (block.className || '').includes('language-plaintext') ||
                        (block.className || '').includes('language-mermaid') ||
                        (block.className || '').includes('language-vega-lite') ||
                        (block.className || '').includes('language-vega')) {
                        return;
                    }
                    try {
                        hljs.highlightElement(block);
                    } catch (e) { }
                });
            }
        }

        if (isFinalRender) {
            // 为代码块添加复制按钮
            element.querySelectorAll('pre code').forEach(block => {
                const pre = block.parentElement;
                if (pre && !pre.querySelector('.copy-btn-wrapper')) {
                    addCopyButtonToCodeBlock(pre, block);
                }
            });
        }

        element.querySelectorAll('img:not([data-image-url])').forEach(img => {
            if (!img.closest('.image-preview-container')) {
                img.style.cursor = 'pointer';
                img.style.maxWidth = '250px';
                img.style.borderRadius = '8px';
                img.dataset.imageUrl = img.src;
            }
        });

        const tables = Array.from(element.querySelectorAll('table'));
        const tableContainers = [];
        tables.forEach(table => {
            let wrapper = table.parentNode;
            if (!wrapper.classList || !wrapper.classList.contains('table-wrapper')) {
                wrapper = document.createElement('div');
                wrapper.className = 'table-wrapper';
                table.parentNode.insertBefore(wrapper, table);
                wrapper.appendChild(table);
            }
            wrapper.style.overflowX = 'auto';
            wrapper.style.webkitOverflowScrolling = 'touch';
            tableContainers.push(wrapper);
        });
        if (isFinalRender) {
            tableContainers.forEach((wrapper, index) => {
                const previous = previousScrollState.tables[index];
                if (previous) {
                    if (typeof previous.scrollLeft === 'number') {
                        wrapper.scrollLeft = previous.scrollLeft;
                    }
                    if (typeof previous.scrollTop === 'number') {
                        wrapper.scrollTop = previous.scrollTop;
                    }
                }
            });

            const latestCodeBlocks = Array.from(element.querySelectorAll('pre'));
            latestCodeBlocks.forEach((block, index) => {
                const previous = previousScrollState.codeBlocks[index];
                if (previous) {
                    if (typeof previous.scrollLeft === 'number') {
                        block.scrollLeft = previous.scrollLeft;
                    }
                    if (typeof previous.scrollTop === 'number') {
                        block.scrollTop = previous.scrollTop;
                    }
                }
            });
        }

        handleFinalRenderAutoFollow({
            isFinalRender,
            hasCitationList,
            element,
            scrollManager,
            shouldAutoScroll
        });

        if (renderTimeout) {
            clearTimeout(renderTimeout);
        }
        if (isFinalRender) {
            try { element.dataset.dynamicProcessed = 'true'; } catch (_) { }
        }
        return vegaRenderPromise || element.__mermaidRenderPromise || null;

    } catch (error) {
        if (renderTimeout) {
            clearTimeout(renderTimeout);
        }
        console.error(`${getToastMessage('console.contentRenderFailed')}:`, error);
        element.textContent = content;
        clearRenderState();
        return null;
    }
}

function createMessageElement(role, messageObject, options = {}) {
    const content = messageObject.content;
    const { historyRender = false } = options || {};

    const messageDiv = document.createElement('div');
    messageDiv.className = `message ${role}`;

    const avatarDiv = document.createElement('div');
    avatarDiv.className = 'avatar';

    if (role === 'user') {
        if (currentUser?.avatar_url) {
            const img = document.createElement('img');
            img.src = currentUser.avatar_url;
            img.alt = getToastMessage('ui.userAvatar');
            img.onerror = () => {
                avatarDiv.innerHTML = '';
                avatarDiv.textContent = currentUser ? (currentUser.username || currentUser.email).charAt(0).toUpperCase() : 'U';
            };
            avatarDiv.appendChild(img);
        } else {
            avatarDiv.textContent = currentUser ? (currentUser.username || currentUser.email).charAt(0).toUpperCase() : 'U';
        }
    } else {
        const img = document.createElement('img');
        img.src = ASSISTANT_AVATAR_SRC;
        img.alt = getToastMessage('ui.aiAssistant');
        avatarDiv.appendChild(img);
    }

    const messageContainerDiv = document.createElement('div');
    messageContainerDiv.className = 'message-container';

    const contentDiv = document.createElement('div');
    contentDiv.className = 'content';
    let renderPromise = null;
    const renderOptions = {
        forcePlainText: role === 'user',
        staticImageRender: !!historyRender && role === 'assistant'
    };
    const messageImageParts = streamImageRuntime.normalizeStreamImageParts(messageObject?.image_parts || messageObject?.image_urls || []);
    const messageImageLayout = streamImageRuntime.normalizeStreamImageLayout(messageObject?.image_layout || []);
    if (renderOptions.forcePlainText) {
        try { contentDiv.dataset.plainText = 'true'; } catch (_) { }
    }
    if (content) {
        let renderPayload = content;
        if (typeof content === 'object' && content !== null && 'content' in content) {
            if (messageObject.reasoning && !content.reasoning) {
                renderPayload = { ...content, reasoning: messageObject.reasoning };
            }
            if (messageImageParts.length > 0) {
                renderPayload = { ...(typeof renderPayload === 'object' ? renderPayload : {}), image_parts: messageImageParts };
            }
            if (messageImageLayout.length > 0) {
                renderPayload = { ...(typeof renderPayload === 'object' ? renderPayload : {}), image_layout: messageImageLayout };
            }
        }
        else if (typeof content === 'string' && messageObject.reasoning) {
            renderPayload = { content, reasoning: messageObject.reasoning };
            if (messageImageParts.length > 0) {
                renderPayload.image_parts = messageImageParts;
            }
            if (messageImageLayout.length > 0) {
                renderPayload.image_layout = messageImageLayout;
            }
        } else if (typeof content === 'string' && messageImageParts.length > 0) {
            renderPayload = { content, image_parts: messageImageParts, image_layout: messageImageLayout };
        }
        renderPromise = renderMessageContent(contentDiv, renderPayload, messageObject.citations || null, true, renderOptions);
    }
    messageContainerDiv.appendChild(contentDiv);

    const actionsDiv = document.createElement('div');
    actionsDiv.className = 'message-actions';

    const getAttachmentQuotePlaceholder = () => {
        const originalContent = messageObject?.content;
        let parts = [];

        if (Array.isArray(originalContent)) {
            parts = originalContent;
        } else if (originalContent && typeof originalContent === 'object' && Array.isArray(originalContent.content)) {
            parts = originalContent.content;
        }

        if (!parts.length) return '';

        const relevantParts = parts.filter(part => part && part.type && part.type !== 'quote');
        if (!relevantParts.length) return '';

        const hasTextPart = relevantParts.some(part =>
            part.type === 'text' && typeof part.text === 'string' && part.text.trim() !== ''
        );
        if (hasTextPart) return '';

        const hasImage = relevantParts.some(part => part.type === 'image_url');
        const hasFile = relevantParts.some(part => part.type === 'file');

        if (hasImage && hasFile) {
            return getToastMessage('ui.quoteAttachmentPlaceholder');
        }
        if (hasImage) {
            return getToastMessage('ui.quoteImagePlaceholder');
        }
        if (hasFile) {
            return getToastMessage('ui.quoteFilePlaceholder');
        }

        return '';
    };

    const quoteBtn = document.createElement('button');
    quoteBtn.className = 'message-action-btn';
    quoteBtn.innerHTML = `
        <svg viewBox="0 0 24 24"><path d="M6 17h3l2-4V7H5v6h3l-2 4zm8 0h3l2-4V7h-6v6h3l-2 4z"/></svg>
        <span>${getToastMessage('ui.quote')}</span>
    `;
    quoteBtn.addEventListener('click', (e) => {
        const btn = e.currentTarget;

        let quoteText = buildCopyTextFromContent(contentDiv).trim();
        if (!quoteText) {
            quoteText = getAttachmentQuotePlaceholder();
        }

        currentQuote = quoteText;
        renderQuotePreview();
        elements.messageInput.focus();

        const allMessages = elements.chatContainer.querySelectorAll('.message');
        const isLastMessage = messageDiv === allMessages[allMessages.length - 1];

        if (isLastMessage) {
            setTimeout(() => {
                smoothScrollToBottom();
            }, 100);
        }

        btn.innerHTML = `
            <svg viewBox="0 0 24 24"><path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"/></svg>
            <span>${getToastMessage('ui.quoted')}</span>
        `;
        setTimeout(() => {
            btn.innerHTML = `
                <svg viewBox="0 0 24 24"><path d="M6 17h3l2-4V7H5v6h3l-2 4zm8 0h3l2-4V7h-6v6h3l-2 4z"/></svg>
                <span>${getToastMessage('ui.quote')}</span>
            `;
        }, 2000);
    });
    actionsDiv.appendChild(quoteBtn);

    if (role === 'user') {
        const editBtn = document.createElement('button');
        editBtn.className = 'message-action-btn';
        editBtn.innerHTML = `
            <svg viewBox="0 0 24 24"><path d="M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04a1.003 1.003 0 0 0 0-1.42l-2.34-2.34a1.003 1.003 0 0 0-1.42 0l-1.83 1.83 3.75 3.75 1.84-1.82z"/></svg>
            <span>${getToastMessage('ui.modify')}</span>
        `;
        editBtn.disabled = true;
        editBtn.style.display = 'none';

        editBtn.addEventListener('click', () => {
            if (editBtn.disabled) return;
            startInlineEditMode();
        });
        actionsDiv.appendChild(editBtn);
    }

    if (role === 'assistant') {
        const copyBtn = document.createElement('button');
        copyBtn.className = 'message-action-btn';
        copyBtn.innerHTML = `
            <svg class="copy-icon" viewBox="0 0 24 24">
                <path d="${ICONS.COPY}"/>
            </svg>
            <span class="copy-text">${getToastMessage('ui.copy')}</span>
        `;
        copyBtn.addEventListener('click', async (e) => {
            const btn = e.currentTarget;
            const textToCopy = buildCopyTextFromContent(contentDiv);

            try {
                if (isNativeApp) {
                    await Clipboard.write({
                        string: textToCopy
                    });
                } else {
                    await navigator.clipboard.writeText(textToCopy);
                }

                btn.querySelector('.copy-text').textContent = getToastMessage('status.copied');
                const iconPath = btn.querySelector('.copy-icon path');
                if (iconPath) {
                    iconPath.setAttribute('d', ICONS.CHECK);
                }

                setTimeout(() => {
                    btn.querySelector('.copy-text').textContent = getToastMessage('status.copy');
                    if (iconPath) {
                        iconPath.setAttribute('d', ICONS.COPY);
                    }
                }, 2000);

            } catch (err) {
                console.error(`${getToastMessage('console.copyFailed')}:`, err);
                showToast(getToastMessage('toast.copyFailed'), 'error');
            }
        });
        actionsDiv.appendChild(copyBtn);

        if (hasPaidAccessForUi()) {
            const exportWrap = document.createElement('div');
            exportWrap.className = 'message-export';
            const exportBtn = document.createElement('button');
            exportBtn.className = 'message-action-btn message-export-btn';
            exportBtn.setAttribute('aria-haspopup', 'true');
            exportBtn.setAttribute('aria-expanded', 'false');
            exportBtn.innerHTML = `
                <svg class="export-icon" viewBox="0 0 24 24">${ICONS.DOWNLOAD}</svg>
                <span>${getToastMessage('ui.export')}</span>
            `;

            const exportMenu = document.createElement('div');
            exportMenu.className = 'message-export-menu';
            const exportOptions = [
                { key: 'ui.exportWord', format: 'word' },
                { key: 'ui.exportPdf', format: 'pdf' },
                { key: 'ui.exportExcel', format: 'excel' },
                { key: 'ui.exportPpt', format: 'ppt' }
            ];

            exportOptions.forEach((option) => {
                const btn = document.createElement('button');
                btn.type = 'button';
                btn.dataset.format = option.format;
                btn.textContent = getToastMessage(option.key);
                btn.addEventListener('click', (event) => {
                    event.stopPropagation();
                    exportMenu.classList.remove('visible');
                    exportBtn.setAttribute('aria-expanded', 'false');
                    handleMessageExport(option.format, {
                        messageElement: messageDiv,
                        contentDiv,
                        messageObject
                    });
                });
                exportMenu.appendChild(btn);
            });

            exportBtn.addEventListener('click', (event) => {
                event.stopPropagation();
                const willOpen = !exportMenu.classList.contains('visible');
                closeMessageExportMenus(exportMenu);
                exportMenu.classList.toggle('visible', willOpen);
                exportBtn.setAttribute('aria-expanded', willOpen ? 'true' : 'false');
            });

            exportWrap.appendChild(exportBtn);
            exportWrap.appendChild(exportMenu);
            actionsDiv.appendChild(exportWrap);
        }
    }
    messageContainerDiv.appendChild(actionsDiv);

    messageDiv.appendChild(avatarDiv);
    messageDiv.appendChild(messageContainerDiv);

    return {
        element: messageDiv,
        promise: (renderPromise && typeof renderPromise.then === 'function') ? renderPromise : null
    };
}

// 编辑模式全局状态
let isEditModeActive = false;
let editModeState = null;

function showEditBar() {
    if (!editModeState || !editModeState.messageEl) return;

    const targetEl = editModeState.messageEl;
    const containerInMsg = document.createElement('div');
    containerInMsg.className = 'inline-edit-container';

    const textarea = document.createElement('textarea');
    textarea.className = 'inline-edit-textarea';
    textarea.value = extractTextFromUserContent(editModeState.originalUserMessage?.content) || '';

    const actions = document.createElement('div');
    actions.className = 'inline-edit-actions';
    const cancelBtn = document.createElement('button');
    cancelBtn.className = 'btn-cancel';
    cancelBtn.textContent = getToastMessage('common.cancel');
    const updateBtn = document.createElement('button');
    updateBtn.className = 'btn-update';
    updateBtn.textContent = getToastMessage('ui.update') || 'Update';

    actions.appendChild(cancelBtn);
    actions.appendChild(updateBtn);
    containerInMsg.appendChild(textarea);
    containerInMsg.appendChild(actions);

    const container = targetEl.querySelector('.message-container');
    const contentDiv = targetEl.querySelector('.content');
    const actionsRow = targetEl.querySelector('.message-actions');
    if (contentDiv) contentDiv.style.display = 'none';
    if (container) {
        if (actionsRow) {
            container.insertBefore(containerInMsg, actionsRow);
        } else {
            container.appendChild(containerInMsg);
        }
    }

    targetEl.classList.add('editing');
    if (actionsRow) actionsRow.style.display = 'none';

    cancelBtn.addEventListener('click', cancelInlineEditMode);
    updateBtn.addEventListener('click', commitInlineEditMode);

    const isMobileUA = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent || '');
    textarea.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
            const shouldSend = isMobileUA ? true : !e.shiftKey;
            if (shouldSend) {
                e.preventDefault();
                commitInlineEditMode();
            }
        }
    });

    editModeState.ui = {
        container: containerInMsg, textarea, cancelBtn, updateBtn
    };

    try {
        document.body.classList.add('editing-inline-mode');
        requestAnimationFrame(() => {
            try {
                textarea.focus();
                const len = textarea.value.length;
                textarea.setSelectionRange(len, len);
            } catch (_) { }
        });
    } catch (_) { }
}

function hideEditBar() {
    if (!editModeState) return;
    const { messageEl, ui } = editModeState;
    if (ui && ui.container && ui.container.parentElement) {
        ui.container.parentElement.removeChild(ui.container);
    }
    if (messageEl) {
        messageEl.classList.remove('editing');
        const actionsRow = messageEl.querySelector('.message-actions');
        if (actionsRow) actionsRow.style.display = '';
        const contentDiv = messageEl.querySelector('.content');
        if (contentDiv) contentDiv.style.display = '';
    }
    try { document.body.classList.remove('editing-inline-mode'); } catch (_) { }
}

function extractTextFromUserContent(content) {
    try {
        if (Array.isArray(content)) {
            const texts = content.filter(p => p && p.type === 'text' && typeof p.text === 'string').map(p => p.text);
            return texts.join('\n').trim();
        }
        if (content && typeof content === 'object' && Array.isArray(content.content)) {
            const texts = content.content.filter(p => p && p.type === 'text' && typeof p.text === 'string').map(p => p.text);
            return texts.join('\n').trim();
        }
        if (typeof content === 'string') return content;
    } catch (_) { }
    return '';
}

function buildResearchTextFromUserContent(content) {
    if (!Array.isArray(content)) return '';
    const textParts = [];
    const fileLabel = getToastMessage('ui.file') || 'File';
    const fileEndLabel = getToastMessage('ui.fileEnd') || 'End of file';

    content.forEach(part => {
        if (part?.type === 'text' && typeof part.text === 'string' && part.text.trim()) {
            textParts.push(part.text.trim());
        } else if (part?.type === 'file' && typeof part.content === 'string' && part.content.trim()) {
            const filename = part.filename || 'attachment';
            textParts.push(`--- ${fileLabel}: ${filename} ---\n${part.content}\n--- ${fileEndLabel} ---`);
        }
    });

    return textParts.join('\n\n').trim();
}

function cloneUserPartsWithNewText(originalContent, newText) {
    const parts = Array.isArray(originalContent)
        ? originalContent.slice()
        : (originalContent && Array.isArray(originalContent.content) ? originalContent.content.slice() : []);

    const nonText = parts.filter(p => p.type !== 'text');
    const result = [];
    if (nonText.length) result.push(...nonText);
    if (newText && newText.trim()) result.push({ type: 'text', text: newText.trim() });
    result.sort((a, b) => {
        const order = { quote: 0, file: 1, image_url: 1, text: 2 };
        return (order[a.type] || 99) - (order[b.type] || 99);
    });
    return result;
}

function refreshEditButtons() {
    try {
        const messagesEls = elements.chatContainer.querySelectorAll('.message');
        if (!messagesEls || messagesEls.length < 2) return;
        const lastEl = messagesEls[messagesEls.length - 1];
        const prevEl = messagesEls[messagesEls.length - 2];

        let prevHasText = false;
        try {
            const chat = chats[currentChatId];
            const msgs = chat?.messages || [];
            if (msgs.length >= 2) {
                const prevMsg = msgs[msgs.length - 2];
                if (prevMsg && prevMsg.role === 'user') {
                    const txt = extractTextFromUserContent(prevMsg.content) || '';
                    prevHasText = txt.trim().length > 0;
                }
            }
        } catch (_) { prevHasText = false; }
        const canShow = lastEl.classList.contains('assistant') && prevEl.classList.contains('user') && prevHasText && !isProcessing && !activeResponses.has(currentChatId) && !isEditModeActive;

        elements.chatContainer.querySelectorAll('.message.user .message-actions .message-action-btn').forEach(btn => {
            if (btn.querySelector('span') && btn.querySelector('span').textContent === getToastMessage('ui.modify')) {
                btn.style.display = 'none';
                btn.disabled = true;
            }
        });
        if (canShow) {
            const targetBtn = prevEl.querySelector('.message-actions .message-action-btn:last-child');
            if (targetBtn && targetBtn.querySelector('span') && targetBtn.querySelector('span').textContent === getToastMessage('ui.modify')) {
                targetBtn.style.display = 'inline-flex';
                targetBtn.disabled = false;
            }
        }
    } catch (_) { }
}

function updateMessageActionLabels() {
    try {
        const quoteText = getToastMessage('ui.quote');
        const copyText = getToastMessage('ui.copy');
        const modifyText = getToastMessage('ui.modify');

        elements.chatContainer
            .querySelectorAll('.message.assistant .message-actions .copy-text')
            .forEach(span => { span.textContent = copyText; });

        elements.chatContainer.querySelectorAll('.message .message-actions').forEach(actions => {
            const buttons = actions.querySelectorAll('.message-action-btn');
            if (buttons.length > 0) {
                const firstSpan = buttons[0].querySelector('span');
                if (firstSpan && !firstSpan.classList.contains('copy-text')) {
                    firstSpan.textContent = quoteText;
                }
            }
            const messageEl = actions.closest('.message');
            if (messageEl && messageEl.classList.contains('user') && buttons.length > 1) {
                const lastBtn = buttons[buttons.length - 1];
                const span = lastBtn?.querySelector('span');
                if (span && !span.classList.contains('copy-text')) {
                    span.textContent = modifyText;
                }
            }
        });
    } catch (_) { }
}

try {
    onAfterLanguageApplied(updateMessageActionLabels);
} catch (_) { }

function appendMessage(role, content) {
    const emptyState = elements.chatContainer.querySelector('.empty-state');
    if (emptyState) emptyState.remove();
    const { element: messageElement, promise: renderPromise } = createMessageElement(role, { content: content });

    elements.chatContainer.appendChild(messageElement);

    if ((role === 'user' || role === 'assistant') && currentChatId) {
        touchChatUpdatedAt(currentChatId);
        scheduleRenderSidebar();
    }

    const scrollHeight = elements.chatContainer.scrollHeight;
    const clientHeight = elements.chatContainer.clientHeight;
    const scrollTop = elements.chatContainer.scrollTop;
    const isScrolledToBottom = scrollHeight - clientHeight <= scrollTop + 20;
    const shouldForceScroll = role === 'user' && !isScrolledToBottom;
    const deferAutoScroll = role === 'user' && shouldForceScroll;

    if (shouldForceScroll || isScrolledToBottom) {
        if (shouldForceScroll) {
            scrollManager.resetUserScrollState();
        }

        if (deferAutoScroll) {
            scrollManager.pendingSmoothScroll = true;
        } else if (shouldForceScroll) {
            scrollManager.smoothScrollToBottom();
        } else {
            scheduleAutoScrollToBottom();
        }

        const ensureActions = () => ensureMessageActionsVisible(messageElement);
        if (renderPromise && typeof renderPromise.then === 'function') {
            renderPromise.finally(() => {
                scheduleAutoScrollToBottom();
                ensureActions();
            });
        } else {
            ensureActions();
        }
    }

    if (scrollManager.pendingSmoothScroll && role !== 'user') {
        scrollManager.pendingSmoothScroll = false;
        scrollManager.smoothScrollToBottom();
    }

    if (isWelcomePage) {
        isWelcomePage = false;
        welcomePageShown = false;
        elements.chatContainer.style.overflowY = 'auto';
    }

    refreshEditButtons();
    return messageElement.querySelector('.message-container');
}

function removeAttachment(attachmentId) {
    const index = attachments.findIndex(a => a.id === attachmentId);
    if (index > -1) {
        attachments.splice(index, 1);
    }
    const element = document.querySelector(`[data-attachment-id="${attachmentId}"]`);
    if (element) element.remove();
    if (attachments.length === 0) elements.attachmentsPreview.classList.remove('has-files');

    updateCharacterCountUI();
    updateSendButton();
    resetCharCountTimer();
}

function getDraftKey(chatId) {
    return chatId || CHAT_DRAFT_DEFAULT_KEY;
}

function persistCurrentDraft(chatId = currentChatId) {
    if (!elements?.messageInput) return;
    const key = getDraftKey(chatId);
    const text = elements.messageInput.value || '';
    const clonedAttachments = attachments.map(att => ({
        file: att.file || null,
        type: att.type,
        content: att.content || null,
        images: att.images || null
    }));
    chatDraftStore.set(key, { text, attachments: clonedAttachments });
}

function restoreDraftForChat(chatId = currentChatId) {
    const key = getDraftKey(chatId);
    const draft = chatDraftStore.get(key);

    clearInputAndAttachments(true);

    if (!draft) {
        updateSendButton();
        resetCharCountTimer();
        updateCharacterCountUI();
        return;
    }

    if (elements.messageInput) {
        elements.messageInput.value = draft.text || '';
        elements.messageInput.style.height = 'auto';
        elements.messageInput.style.height = `${elements.messageInput.scrollHeight}px`;
    }

    if (Array.isArray(draft.attachments)) {
        draft.attachments.forEach((att) => {
            if (!att || (!att.file && !att.content && !att.images)) return;
            const isImage = att.type === 'image' || (att.file?.type || '').startsWith('image/');
            const newId = addAttachment(att.file, isImage ? 'image' : (att.type || 'file'));
            if (att.content) {
                completeUpload(newId, att.content, att.images || null);
            } else if (att.images) {
                completeUpload(newId, '', att.images);
            }
        });
    }

    updateCharacterCountUI();
    updateSendButton();
    resetCharCountTimer();
}

function cleanupEmptyMessagePlaceholders() {
    const container = elements.chatContainer;
    if (!container) return;
    const messages = container.querySelectorAll('.message');
    messages.forEach(message => {
        const contentDiv = message.querySelector('.content');
        if (!contentDiv) return;
        const hasSpinner = !!contentDiv.querySelector('.thinking-indicator-new');
        const textContent = (contentDiv.textContent || '').trim();
        const hasMedia = contentDiv.querySelector('img, video, pre, code, table, blockquote, ul, ol, .file-chip-display, .rendered-markdown, .assistant-card, .image-result');
        const hasExternalAttachments = message.querySelector('.attachments-preview, .file-chip-display');
        if ((hasSpinner || textContent.length === 0) && !hasMedia && !hasExternalAttachments) {
            message.remove();
        }
    });
}

async function upsertSlashCommand(command, editingName = '') {
    const normalizedName = normalizeSlashCommandName(command?.name || '');
    const payload = {
        name: normalizedName,
        prompt: command?.prompt || '',
        description: command?.description || '',
        is_enabled: command?.is_enabled !== false,
        editingName: editingName || ''
    };
    if (!payload.name || !payload.prompt) {
        throw new Error('invalid_slash_command');
    }

    if (!currentUser) {
        const commands = loadCustomSlashCommands();
        const nameLower = payload.name.toLowerCase();
        const filtered = commands.filter(cmd => String(cmd?.name || '').toLowerCase() !== nameLower);
        if (editingName && normalizeSlashCommandName(editingName).toLowerCase() !== nameLower) {
            filtered.unshift({ name: payload.name, prompt: payload.prompt, description: payload.description });
        } else {
            filtered.unshift({ name: payload.name, prompt: payload.prompt, description: payload.description });
        }
        saveCustomSlashCommands(filtered);
        return filtered;
    }

    if (editingName && normalizeSlashCommandName(editingName).toLowerCase() !== payload.name.toLowerCase()) {
        await makeApiRequest('slash-commands/delete', {
            method: 'POST',
            body: JSON.stringify({ name: editingName })
        });
    }

    await makeApiRequest('slash-commands', {
        method: 'POST',
        body: JSON.stringify(payload)
    });
    return await ensureSlashCommandCache(true);
}

async function deleteSlashCommandByName(name) {
    const normalized = normalizeSlashCommandName(name || '');
    if (!normalized) return [];
    if (!currentUser) {
        const commands = loadCustomSlashCommands();
        const nextCommands = commands.filter(cmd => normalizeSlashCommandName(cmd?.name || '') !== normalized);
        saveCustomSlashCommands(nextCommands);
        return nextCommands;
    }
    await makeApiRequest('slash-commands/delete', {
        method: 'POST',
        body: JSON.stringify({ name: normalized })
    });
    return await ensureSlashCommandCache(true);
}

function readPendingTurnState() {
    try {
        const raw = localStorage.getItem(PENDING_TURN_STORAGE_KEY);
        if (!raw) return null;
        const parsed = JSON.parse(raw);
        if (!parsed || !parsed.chatId || !parsed.userMessageId) return null;
        return parsed;
    } catch (_) {
        return null;
    }
}

function persistPendingTurnState(chatId, userMessageId, isNewChat) {
    if (!chatId || !userMessageId) return;
    try {
        localStorage.setItem(PENDING_TURN_STORAGE_KEY, JSON.stringify({
            chatId,
            userMessageId,
            isNewChat: !!isNewChat,
            timestamp: Date.now()
        }));
    } catch (_) { }
}

function clearPendingTurnState(chatId = null) {
    try {
        const pending = readPendingTurnState();
        if (!pending) {
            localStorage.removeItem(PENDING_TURN_STORAGE_KEY);
            return;
        }
        if (!chatId || pending.chatId === chatId) {
            localStorage.removeItem(PENDING_TURN_STORAGE_KEY);
        }
    } catch (_) { }
}

function messageHasClientId(message, targetId) {
    if (!message || !targetId) return false;
    const id = message.client_message_id || message.clientMessageId;
    return id === targetId;
}

function isMessageContentEmpty(content) {
    if (content == null) return true;
    if (typeof content === 'string') return content.trim() === '';
    if (Array.isArray(content)) {
        if (content.length === 0) return true;
        return content.every(part => {
            if (!part) return true;
            if (part.type === 'text') return !String(part.text || '').trim();
            return false;
        });
    }
    if (typeof content === 'object' && Object.prototype.hasOwnProperty.call(content, 'content')) {
        return isMessageContentEmpty(content.content);
    }
    return false;
}

function isAssistantPlaceholderMessage(message) {
    return !!message && message.role === 'assistant' && isMessageContentEmpty(message.content);
}

async function cleanupPendingTurnOnStartup() {
    const pending = readPendingTurnState();
    if (!pending) return;
    const chat = chats?.[pending.chatId];
    if (!chat || !Array.isArray(chat.messages)) {
        clearPendingTurnState(pending.chatId);
        return;
    }

    const messages = chat.messages;
    let changed = false;

    if (messages.length > 0) {
        const last = messages[messages.length - 1];
        const prev = messages[messages.length - 2];
        if (last && last.role === 'assistant' && isAssistantPlaceholderMessage(last) && messageHasClientId(prev, pending.userMessageId)) {
            messages.pop();
            changed = true;
        }
        const currentLast = messages[messages.length - 1];
        if (currentLast && currentLast.role === 'user' && messageHasClientId(currentLast, pending.userMessageId)) {
            messages.pop();
            changed = true;
        }
    }

    const shouldDeleteChat = pending.isNewChat
        && String(pending.chatId).startsWith('temp_')
        && (!chat.messages || chat.messages.length === 0);

    if (shouldDeleteChat) {
        delete chats[pending.chatId];
        localStorage.removeItem(`pending_chat_${pending.chatId}`);
        if (currentChatId === pending.chatId) {
            currentChatId = null;
            showEmptyState();
            scheduleRenderSidebar();
            routeManager.navigateToHome({ replace: true, force: true, silent: true });
        } else {
            scheduleRenderSidebar();
        }
    } else if (changed) {
        scheduleRenderSidebar();
        if (currentChatId === pending.chatId) {
            loadChat(pending.chatId).catch(err => console.warn('Failed to reload chat after pending cleanup:', err));
        }
    }

    if (changed || shouldDeleteChat) {
        try {
            const userIdForDb = currentUser?.id || 'guest';
            await saveChatsToDB(userIdForDb, chats);
        } catch (error) {
            console.warn('Failed to persist pending-turn cleanup:', error);
        }
    }

    clearPendingTurnState(pending.chatId);
}

function normalizeParsedResult(result) {
    if (result && typeof result === 'object' && !Array.isArray(result)) {
        const text = typeof result.text === 'string' ? result.text : (result.text == null ? '' : String(result.text));
        const images = result.images && typeof result.images === 'object' ? result.images : null;
        return { text, images };
    }
    return { text: typeof result === 'string' ? result : (result == null ? '' : String(result)), images: null };
}

function buildImagePartsFromAttachment(attachment) {
    if (!attachment?.images || typeof attachment.images !== 'object') return [];
    const parts = [];
    Object.values(attachment.images).forEach((image) => {
        if (!image || !image.data) return;
        const mime = image.mime || 'image/png';
        parts.push({
            type: 'image_url',
            image_url: { url: `data:${mime};base64,${image.data}` }
        });
    });
    return parts;
}

async function processAndAttachFile(file) {
    if (!currentUser) {
        await ensureStorageAccess({ strict: false });
    }
    // 生成内容哈希用于重复检测
    const contentHash = await generateFileHash(file);
    const isDuplicate = attachments.some(att => att.contentHash === contentHash);
    if (isDuplicate) {
        showToast(getToastMessage('toast.fileDuplicate'), 'info');
        return;
    }

    if (isSearchModeActive) {
        if (!canUseSearchAttachments()) {
            showToast(getToastMessage('toast.searchAttachmentsProOnly'), 'info');
            return;
        }
        if (file.type.startsWith('image/')) {
            const hasImage = attachments.some(att => att.type === 'image');
            if (hasImage) {
                showToast(getToastMessage('toast.searchImageLimit'), 'info');
                return;
            }
        }
    }

    const isGuest = !currentUser;
    const maxSize = isGuest ? GUEST_FILE_SIZE_LIMIT : LOGGED_IN_FILE_SIZE_LIMIT;
    const limitInMB = (maxSize / (1024 * 1024)).toFixed(1);

    if (file.size > maxSize) {
        const userType = isGuest ? getToastMessage('ui.guest') : getToastMessage('ui.you');
        showToast(getToastMessage('toast.fileTooLarge', { filename: file.name, userType: userType, limit: limitInMB }), 'error');
        throw new Error('File size exceeds limit');
    }

    const attachmentId = addAttachment(file, file.type.startsWith('image/') ? 'image' : 'file', contentHash);

    try {
        let content = '';
        let images = null;
        const extension = file.name.split('.').pop()?.toLowerCase();
        const allowRichDocParsing = shouldAllowRichDocParsing();
        let allowEmptyFile = false;

        if (file.type.startsWith('image/')) {
            content = await imageToBase64(file);
        } else if (extension === 'docx') {
            const { readDocxFile } = await getFileParsers();
            ({ text: content, images } = normalizeParsedResult(await readDocxFile(file, { includeImages: allowRichDocParsing })));
        } else if (extension === 'pdf') {
            const { readPdfFile } = await getFileParsers();
            ({ text: content, images } = normalizeParsedResult(await readPdfFile(file, { allowImageFallback: allowRichDocParsing })));
        } else if (['xlsx', 'xls', 'csv'].includes(extension)) {
            const { readExcelFile } = await getFileParsers();
            content = await readExcelFile(file);
        } else if (['pptx'].includes(extension)) {
            try {
                await loadScript('/libs/turndown.min.js', 'turndownService');
                await loadScript('/libs/turndown-plugin-gfm.min.js', 'turndownPluginGfm');
                if (!window.turndownService || !window.turndownService.turndown) {
                    const Ctor = typeof window.turndownService === 'function' && !window.turndownService.turndown
                        ? window.turndownService
                        : window.TurndownService;
                    if (typeof Ctor === 'function') {
                        window.turndownService = new Ctor({ headingStyle: 'atx', codeBlockStyle: 'fenced' });
                        if (window.turndownPluginGfm && window.turndownPluginGfm.gfm && window.turndownService.use) {
                            window.turndownService.use(window.turndownPluginGfm.gfm);
                        }
                    }
                }
                const { readPptxFile } = await getFileParsers();
                ({ text: content, images } = normalizeParsedResult(await readPptxFile(file, { includeImages: allowRichDocParsing })));
            } catch (pptxError) {
                const errorMessage = pptxError.message || getToastMessage('errors.markdownConverterLoadFailed');
                showToast(`${getToastMessage('console.skipFile', { filename: file.name })}: ${errorMessage}`, 'info');
                removeAttachment(attachmentId);
                return;
            }
        } else if (isPlainTextFile(file.name) || file.type.startsWith('text/')) {
            content = await readFileAsText(file);
        } else if (!file.type || file.type === 'application/octet-stream') {
            const isBinary = await isLikelyBinaryFile(file);
            if (isBinary) {
                showToast(getToastMessage('toast.unsupportedFileFormat', { extension: extension || 'binary' }), 'error');
                removeAttachment(attachmentId);
                throw new Error(`Unsupported binary file: ${file.name}`);
            }
            content = await readFileAsText(file);
        } else {
            showToast(getToastMessage('toast.unsupportedFileFormat', { extension: extension }), 'error');
            removeAttachment(attachmentId);
            throw new Error(`Unsupported file type: .${extension}`);
        }

        if (extension === 'pdf' && !allowRichDocParsing && !(content || '').trim()) {
            allowEmptyFile = true;
            showToast(getToastMessage('fileManagement.pdfScanVersion'), 'info');
        }

        const attachment = attachments.find(a => a.id === attachmentId);
        if (attachment) {
            attachment.allowEmpty = allowEmptyFile;
        }
        completeUpload(attachmentId, content, images);

        const { isOverLimit } = updateCharacterCountUI();
        if (isOverLimit) {
            const { toastKey } = getCharacterLimitInfo();
            showToast(getToastMessage(toastKey), 'error');
        }

    } catch (error) {
        showToast(`${getToastMessage('toast.fileParseFailed', { filename: file.name })}: ${error.message || getToastMessage('toast.unknownError')}`, 'error');
        removeAttachment(attachmentId);
        throw error;
    }
}

async function handlePaste(e) {
    const items = e.clipboardData?.items;
    if (!items) return;

    const filePromises = [];
    let imagePasted = false;

    for (const item of items) {
        if (item.kind === 'file' && item.type.startsWith('image/')) {
            imagePasted = true;
            const fileBlob = item.getAsFile();
            const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
            const file = new File([fileBlob], `${getToastMessage('ui.screenshot')}-${timestamp}.png`, { type: fileBlob.type });

            filesCurrentlyProcessing++;
            updateSendButton();

            const promise = processAndAttachFile(file)
                .catch(error => {
                    console.log(`${getToastMessage('console.pasteFileProcessFailed')}: ${error.message}`);
                })
                .finally(() => {
                    filesCurrentlyProcessing--;
                });

            filePromises.push(promise);
        }
    }

    if (imagePasted) {
        e.preventDefault();
        Promise.all(filePromises).then(() => {
            updateSendButton();
            resetCharCountTimer();
        });
    }
}

function addAttachment(file, type, contentHash = null) {
    const attachmentId = attachmentIdCounter++;
    const attachment = { id: attachmentId, file, type, content: null, images: null, contentHash };
    attachments.push(attachment);
    const element = document.createElement('div');
    element.dataset.attachmentId = attachmentId;
    if (type === 'image') {
        element.className = 'img-preview uploading';
    } else {
        element.className = 'file-chip uploading';
    }
    element.innerHTML = `
                <span class="file-name">${type === 'text' ? file.name : ''}</span>
                <div class="upload-progress-container">
                     <svg class="progress-circle" viewBox="0 0 22 22">
                        <circle class="progress-track" cx="11" cy="11" r="10"></circle>
                        <circle class="progress-fill" id="progress-${attachmentId}" cx="11" cy="11" r="10"></circle>
                    </svg>
                </div>
                 <button class="remove-btn">×</button>
            `;
    element.querySelector('.remove-btn').addEventListener('click', () => removeAttachment(attachmentId));
    elements.attachmentsPreview.appendChild(element);
    elements.attachmentsPreview.classList.add('has-files');
    updateSendButton();
    return attachmentId;
}

function completeUpload(attachmentId, content, images = null) {
    const attachment = attachments.find(a => a.id === attachmentId);
    if (!attachment) return;
    attachment.content = content;
    attachment.images = images;
    const element = document.querySelector(`[data-attachment-id="${attachmentId}"]`);
    if (element) {
        element.classList.remove('uploading');
        if (attachment.type === 'image') {
            element.innerHTML = '';
            const img = document.createElement('img');
            img.src = content;
            img.alt = attachment.file?.name || '';
            element.appendChild(img);
        } else {
            element.innerHTML = '';
            const fileName = document.createElement('span');
            fileName.className = 'file-name';
            fileName.textContent = attachment.file?.name || '';
            element.appendChild(fileName);
        }
        const removeBtn = document.createElement('button');
        removeBtn.className = 'remove-btn';
        removeBtn.textContent = '×';
        element.appendChild(removeBtn);
        element.querySelector('.remove-btn').addEventListener('click', () => removeAttachment(attachmentId));
    }
}

function blobToBase64(blob) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onerror = reject;
        reader.onload = () => {
            const base64String = reader.result.split(',')[1];
            resolve(base64String);
        };
        reader.readAsDataURL(blob);
    });
}

function base64ToBlob(base64, contentType) {
    try {
        const byteCharacters = atob(base64);
        const byteArrays = [];
        const sliceSize = 1024;
        for (let offset = 0; offset < byteCharacters.length; offset += sliceSize) {
            const slice = byteCharacters.slice(offset, offset + sliceSize);
            const byteNumbers = new Array(slice.length);
            for (let i = 0; i < slice.length; i++) {
                byteNumbers[i] = slice.charCodeAt(i);
            }
            const byteArray = new Uint8Array(byteNumbers);
            byteArrays.push(byteArray);
        }
        return new Blob(byteArrays, { type: contentType || 'application/octet-stream' });
    } catch (e) {
        console.error('Failed to convert base64 to Blob:', e);
        throw e;
    }
}

async function imageToBase64(file) {
    const isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);

    if ((isMobile && file.size > 300000) || (!isMobile && file.size > 1000000)) {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const img = new Image();
        const compressedFile = await new Promise((resolve) => {
            img.onload = () => {
                const maxWidth = isMobile ? 800 : 1200;
                const ratio = Math.min(1, maxWidth / img.width);
                canvas.width = img.width * ratio;
                canvas.height = img.height * ratio;
                ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
                canvas.toBlob(resolve, 'image/jpeg', isMobile ? 0.7 : 0.85);
            };
            img.src = URL.createObjectURL(file);
        });
        file = compressedFile;
    }
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => resolve(reader.result);
        reader.onerror = error => reject(error);
    });
}

function readFileAsText(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsText(file);
        reader.onload = () => resolve(reader.result);
        reader.onerror = error => reject(error);
    });
}

async function isLikelyBinaryFile(file) {
    try {
        const sample = file.slice(0, Math.min(file.size, 4096));
        const buffer = await sample.arrayBuffer();
        const bytes = new Uint8Array(buffer);
        if (bytes.length === 0) return false;
        let nonTextCount = 0;
        for (let i = 0; i < bytes.length; i++) {
            const b = bytes[i];
            if (b === 0) return true;
            if (b < 7 || (b > 13 && b < 32)) {
                nonTextCount++;
            }
        }
        return (nonTextCount / bytes.length) > 0.3;
    } catch (err) {
        return false;
    }
}

const DOC_ATTACHMENT_EXTENSIONS = new Set(['pdf', 'docx', 'pptx', 'csv', 'xls', 'xlsx']);
const DOC_ATTACHMENT_MARKER_PREFIX = '[DOC_ATTACHMENTS:';
const DOC_ATTACHMENT_MARKER_SUFFIX = ']';
const DOC_DATA_REMOTE_SAVE_DEBOUNCE_MS = 1200;
const DOC_IMAGE_UPLOAD_DEBOUNCE_MS = 1500;
const DOC_IMAGE_UPLOAD_BATCH_SIZE = SYNC_QUEUE_BATCH_SIZE;
const DOC_IMAGE_UPLOAD_BATCH_BYTES = SYNC_QUEUE_BATCH_BYTES;
// keepalive request body has browser-imposed size limits (commonly around 64KB).
const KEEPALIVE_SAFE_BODY_BYTES = 60 * 1024;
const docDataSaveTimers = new Map();
const docDataSaveSignatures = new Map();
const docImageUploadTimers = new Map();
const docImageUploadCache = new Map();
const pendingDocDataSaves = new Set();
const pendingDocImageUploads = new Set();
const DOC_IMAGE_UPLOAD_QUEUE_KEY = 'pending_doc_image_uploads';
let hasResumedDocImageUploads = false;

function loadDocImageUploadQueue() {
    if (!currentUser?.id) return { items: {}, order: [] };
    return loadPersistentQueue({
        baseKey: DOC_IMAGE_UPLOAD_QUEUE_KEY,
        userId: currentUser.id,
        legacyKey: DOC_IMAGE_UPLOAD_QUEUE_KEY
    });
}

function saveDocImageUploadQueue(queue) {
    if (!currentUser?.id) return;
    savePersistentQueue({
        baseKey: DOC_IMAGE_UPLOAD_QUEUE_KEY,
        userId: currentUser.id,
        queue,
        shouldKeepItem: (item) => Array.isArray(item?.hashes) && item.hashes.length > 0
    });
}

function queueDocImageUpload(chatId, hashes = null) {
    if (!currentUser || !chatId) return;
    let hashList = Array.isArray(hashes) ? hashes.filter(Boolean) : null;
    if (!hashList || hashList.length === 0) {
        const chat = chats?.[chatId];
        if (!chat) return;
        hashList = Array.from(collectCidHashesFromChat(chat));
    }
    if (hashList.length === 0) return;
    const queue = loadDocImageUploadQueue();
    const existing = new Set(queue.items?.[chatId]?.hashes || []);
    hashList.forEach(hash => existing.add(hash));
    const item = { hashes: Array.from(existing), updatedAt: Date.now() };
    upsertQueueItem(queue, chatId, item);
    saveDocImageUploadQueue(queue);
}

function clearDocImageUploadQueueForChat(chatId) {
    if (!currentUser || !chatId) return;
    const queue = loadDocImageUploadQueue();
    if (!queue.items?.[chatId]) return;
    removeQueueItem(queue, chatId);
    saveDocImageUploadQueue(queue);
}

function resumePendingDocImageUploadsOnce() {
    if (!currentUser || hasResumedDocImageUploads) return;
    hasResumedDocImageUploads = true;
    const queue = loadDocImageUploadQueue();
    Object.entries(queue.items || {}).forEach(([chatId, entry]) => {
        if (!Array.isArray(entry?.hashes) || entry.hashes.length === 0) return;
        uploadDocImagesForChat(chatId, entry.hashes);
    });
}

function resetDocImageUploadRuntimeState() {
    pendingDocImageUploads.clear();
    docImageUploadTimers.forEach(timer => clearTimeout(timer));
    docImageUploadTimers.clear();
    hasResumedDocImageUploads = false;
}

function extractDocAttachmentExtensionsFromContent(content) {
    if (!Array.isArray(content)) return [];
    const extensions = new Set();
    content.forEach((part) => {
        if (part?.type !== 'file' || typeof part.filename !== 'string') return;
        const ext = part.filename.split('.').pop()?.toLowerCase();
        if (ext && DOC_ATTACHMENT_EXTENSIONS.has(ext)) {
            extensions.add(ext);
        }
    });
    return Array.from(extensions);
}

function buildDocAttachmentMarkerFromContent(content) {
    const extensions = extractDocAttachmentExtensionsFromContent(content);
    if (extensions.length === 0) return '';
    return `${DOC_ATTACHMENT_MARKER_PREFIX}${extensions.join(',')}${DOC_ATTACHMENT_MARKER_SUFFIX}`;
}

function appendDocAttachmentMarker(text, content) {
    if (typeof text !== 'string') return text;
    if (text.includes(DOC_ATTACHMENT_MARKER_PREFIX)) return text;
    const marker = buildDocAttachmentMarkerFromContent(content);
    if (!marker) return text;
    return `${text}\n\n${marker}`;
}

function hasDocAttachmentsInHistory(messages) {
    if (!Array.isArray(messages)) return false;
    for (const msg of messages) {
        const content = msg?.content;
        if (typeof content === 'string' && content.includes(DOC_ATTACHMENT_MARKER_PREFIX)) {
            return true;
        }
        if (!Array.isArray(content)) continue;
        for (const part of content) {
            if (part?.type === 'text' && typeof part.text === 'string' && part.text.includes(DOC_ATTACHMENT_MARKER_PREFIX)) {
                return true;
            }
            if (part?.type !== 'file' || typeof part.filename !== 'string') continue;
            const ext = part.filename.split('.').pop()?.toLowerCase();
            if (ext && DOC_ATTACHMENT_EXTENSIONS.has(ext)) {
                return true;
            }
        }
    }
    return false;
}

const docAttachmentTextCache = new Map();

function buildDocAttachmentContextText(entries) {
    if (!Array.isArray(entries) || entries.length === 0) return '';
    const fileLabel = getToastMessage('ui.file') || 'File';
    const fileEndLabel = getToastMessage('ui.fileEnd') || 'End of file';
    return entries.map(entry => {
        const filename = entry.filename || 'attachment';
        const text = typeof entry.text === 'string' ? entry.text.trim() : '';
        if (!text) return '';
        return `--- ${fileLabel}: ${filename} ---\n${text}\n--- ${fileEndLabel} ---`;
    }).filter(Boolean).join('\n\n');
}

async function saveDocDataToRemote(chatId, docAttachments, cidHashes) {
    if (!currentUser || !chatId) return;
    try {
        const result = await makeApiRequest('docdata/save', {
            method: 'POST',
            keepalive: true,
            body: JSON.stringify({
                chatId,
                docAttachments: Array.isArray(docAttachments) ? docAttachments : [],
                cidHashes: Array.isArray(cidHashes) ? cidHashes : []
            })
        });
        if (!result?.success) {
            console.warn('Failed to persist doc data to R2:', result?.error || 'unknown_error');
        }
    } catch (error) {
        console.warn('Failed to persist doc data to R2:', error);
    }
}

async function fetchDocDataFromRemote(chatId) {
    if (!currentUser || !chatId) return null;
    try {
        const result = await makeApiRequest(`docdata/load?chatId=${encodeURIComponent(chatId)}`, {
            method: 'GET'
        });
        if (!result?.success) return null;
        return result;
    } catch (error) {
        console.warn('Failed to load doc data from R2:', error);
        return null;
    }
}

async function deleteDocDataFromRemote(chatIds) {
    if (!currentUser) return;
    const ids = Array.isArray(chatIds) ? chatIds.filter(Boolean) : [];
    if (ids.length === 0) return;
    try {
        await makeApiRequest('docdata/delete', {
            method: 'POST',
            body: JSON.stringify({ chatIds: ids })
        });
    } catch (error) {
        console.warn('Failed to delete doc data from R2:', error);
    }
}

async function deleteDocImagesFromRemote(chatId) {
    if (!currentUser || !chatId) return;
    try {
        await makeApiRequest('docdata/image-delete-chat', {
            method: 'POST',
            body: JSON.stringify({ chatId })
        });
    } catch (error) {
        console.warn('Failed to delete doc images from R2:', error);
    }
    clearDocImageUploadQueueForChat(chatId);
}

async function moveDocDataRemote(fromChatId, toChatId) {
    if (!currentUser || !fromChatId || !toChatId || fromChatId === toChatId) return;
    try {
        await makeApiRequest('docdata/move', {
            method: 'POST',
            body: JSON.stringify({ fromChatId, toChatId })
        });
    } catch (error) {
        console.warn('Failed to move doc data on R2:', error);
    }
}

function transferDocDataCaches(fromChatId, toChatId) {
    if (!fromChatId || !toChatId || fromChatId === toChatId) return;
    if (docAttachmentTextCache.has(fromChatId)) {
        docAttachmentTextCache.set(toChatId, docAttachmentTextCache.get(fromChatId));
        docAttachmentTextCache.delete(fromChatId);
    }
    if (docDataSaveSignatures.has(fromChatId)) {
        docDataSaveSignatures.set(toChatId, docDataSaveSignatures.get(fromChatId));
        docDataSaveSignatures.delete(fromChatId);
    }
    if (docDataSaveTimers.has(fromChatId)) {
        clearTimeout(docDataSaveTimers.get(fromChatId));
        docDataSaveTimers.delete(fromChatId);
    }
    if (docImageUploadCache.has(fromChatId)) {
        docImageUploadCache.delete(fromChatId);
    }
    if (docImageUploadTimers.has(fromChatId)) {
        clearTimeout(docImageUploadTimers.get(fromChatId));
        docImageUploadTimers.delete(fromChatId);
    }
    clearDocImageUploadQueueForChat(fromChatId);
}

async function uploadDocImagesForChat(chatId, hashes = null) {
    if (!currentUser || !chatId || !sessionId) return;
    const queue = loadDocImageUploadQueue();
    const queuedHashes = Array.isArray(queue?.items?.[chatId]?.hashes) ? queue.items[chatId].hashes : [];
    const chat = chats?.[chatId];
    let hashList = Array.isArray(hashes) && hashes.length > 0
        ? hashes
        : (queuedHashes.length > 0 ? queuedHashes : (chat ? Array.from(collectCidHashesFromChat(chat)) : []));
    if (hashList.length === 0) return;
    queueDocImageUpload(chatId, hashList);

    let uploadedSet = docImageUploadCache.get(chatId);
    if (!uploadedSet) {
        uploadedSet = new Set();
        docImageUploadCache.set(chatId, uploadedSet);
    }

    const queueItem = queue.items?.[chatId];
    if (queueItem && (shouldDeferQueueItem(queueItem) || (Number(queueItem.retryCount) || 0) >= SYNC_QUEUE_MAX_RETRIES)) {
        return;
    }
    let cursor = 0;
    const skippedHashes = new Set();
    const pickNextUnit = async () => {
        while (cursor < hashList.length) {
            const hash = hashList[cursor];
            cursor += 1;
            if (uploadedSet.has(hash)) continue;
            if (await LocalStore.isUploadedForChat(hash, chatId)) {
                uploadedSet.add(hash);
                continue;
            }
            try {
                const blob = await LocalStore.getImage(hash, chatId);
                if (!blob) {
                    skippedHashes.add(hash);
                    continue;
                }
                const bytes = blob.size || 0;
                return {
                    id: hash,
                    hash,
                    blob,
                    bytes
                };
            } catch (error) {
                console.warn('Failed to prepare doc image for upload:', error);
                skippedHashes.add(hash);
            }
        }
        return null;
    };

    const sendBatch = async (batch) => {
        const formData = new FormData();
        formData.append('chatId', chatId);
        batch.forEach(item => {
            formData.append('hash', item.hash);
            formData.append('mime', item.blob?.type || 'application/octet-stream');
            formData.append('file', item.blob, `${item.hash}.bin`);
        });

        const totalBytes = batch.reduce((sum, item) => sum + (Number(item?.bytes) || 0), 0);
        const baseRequest = {
            method: 'POST',
            headers: {
                'X-Session-ID': sessionId
            },
            body: formData
        };
        const shouldUseKeepalive = totalBytes > 0 && totalBytes <= KEEPALIVE_SAFE_BODY_BYTES;

        let response;
        try {
            response = await fetch('/api/docdata/image-save-batch', {
                ...baseRequest,
                keepalive: shouldUseKeepalive
            });
        } catch (error) {
            // Large keepalive payload may throw TypeError in some browsers; fallback to normal request.
            if (shouldUseKeepalive && error?.name === 'TypeError') {
                response = await fetch('/api/docdata/image-save-batch', baseRequest);
            } else {
                throw error;
            }
        }
        if (response.status === 401) {
            return { ok: false, stopReason: 'auth', attempted: batch.map(item => item.id) };
        }
        if (!response.ok) {
            const errorText = await response.text().catch(() => '');
            return { ok: false, error: errorText || 'upload_failed', attempted: batch.map(item => item.id) };
        }
        const result = await response.json().catch(() => null);
        const uploaded = Array.isArray(result?.uploaded) ? result.uploaded : [];
        return { ok: true, uploaded, attempted: batch.map(item => item.id) };
    };

    await runSyncQueueWorker({
        pickNextUnit,
        sendBatch,
        batchSize: DOC_IMAGE_UPLOAD_BATCH_SIZE,
        batchBytes: DOC_IMAGE_UPLOAD_BATCH_BYTES,
        onUnitSuccess: async (unit) => {
            uploadedSet.add(unit.hash);
            await LocalStore.markUploadedForChat(unit.hash, chatId);
            if (queue.items?.[chatId]) {
                resetQueueItemFailure(queue.items[chatId]);
                queue.items[chatId].updatedAt = Date.now();
            }
        },
        onUnitFailure: () => {
            if (queue.items?.[chatId]) {
                markQueueItemFailure(queue.items[chatId], {
                    baseMs: SYNC_QUEUE_BACKOFF_BASE_MS,
                    maxMs: SYNC_QUEUE_BACKOFF_MAX_MS,
                    fixedDelayMs: SYNC_QUEUE_RETRY_DELAY_MS
                });
                queue.items[chatId].updatedAt = Date.now();
            }
        },
        stopWhen: (result) => {
            const item = queue.items?.[chatId];
            return !!(result?.stopReason === 'auth'
                || (item && (shouldDeferQueueItem(item) || (Number(item.retryCount) || 0) >= SYNC_QUEUE_MAX_RETRIES)));
        },
        onStop: (result) => {
            if (result?.stopReason === 'auth') {
                resetDocImageUploadRuntimeState();
                return;
            }
            showSyncQueueRetryToastOnce(result);
        }
    });

    if (queue.items?.[chatId]) {
        saveDocImageUploadQueue(queue);
    }
    const remaining = hashList.filter(hash => !uploadedSet.has(hash) && !skippedHashes.has(hash));
    if (remaining.length > 0) {
        queueDocImageUpload(chatId, remaining);
    } else {
        clearDocImageUploadQueueForChat(chatId);
    }
}

function scheduleDocImageUpload(chatId, hashes = null) {
    if (!currentUser || !chatId) return;
    const hashList = Array.isArray(hashes) && hashes.length > 0 ? hashes : null;
    pendingDocImageUploads.add(chatId);
    queueDocImageUpload(chatId, hashList);
    if (docImageUploadTimers.has(chatId)) {
        clearTimeout(docImageUploadTimers.get(chatId));
    }
    const timer = setTimeout(() => {
        docImageUploadTimers.delete(chatId);
        uploadDocImagesForChat(chatId, hashList);
        pendingDocImageUploads.delete(chatId);
    }, DOC_IMAGE_UPLOAD_DEBOUNCE_MS);
    docImageUploadTimers.set(chatId, timer);
}

function scheduleDocDataSave(chatId) {
    if (!currentUser || !chatId) return;
    const chat = chats?.[chatId];
    if (!chat || !Array.isArray(chat.docAttachments) || chat.docAttachments.length === 0) return;
    const cidHashes = Array.from(collectCidHashesFromChat(chat));
    if (cidHashes.length === 0) return;
    const signature = JSON.stringify({
        docAttachments: chat.docAttachments,
        cidHashes
    });
    const previousSignature = docDataSaveSignatures.get(chatId);
    if (signature === previousSignature) return;
    docDataSaveSignatures.set(chatId, signature);

    if (docDataSaveTimers.has(chatId)) {
        clearTimeout(docDataSaveTimers.get(chatId));
    }
    pendingDocDataSaves.add(chatId);
    const timer = setTimeout(() => {
        docDataSaveTimers.delete(chatId);
        saveDocDataToRemote(chatId, chat.docAttachments, cidHashes);
        pendingDocDataSaves.delete(chatId);
    }, DOC_DATA_REMOTE_SAVE_DEBOUNCE_MS);
    docDataSaveTimers.set(chatId, timer);
}

function flushPendingDocUploads() {
    if (!currentUser) return;
    const docChats = Array.from(pendingDocDataSaves);
    const imageChats = Array.from(pendingDocImageUploads);
    docChats.forEach(chatId => {
        const chat = chats?.[chatId];
        if (!chat || !Array.isArray(chat.docAttachments)) return;
        const cidHashes = Array.from(collectCidHashesFromChat(chat));
        if (cidHashes.length === 0) return;
        saveDocDataToRemote(chatId, chat.docAttachments, cidHashes);
    });
    imageChats.forEach(chatId => {
        queueDocImageUpload(chatId);
        uploadDocImagesForChat(chatId);
    });
}

function cacheDocAttachmentsForChat(chatId, content) {
    if (!chatId || !Array.isArray(content)) return;
    const chat = chats?.[chatId];
    if (!chat) return;
    const entries = content
        .filter(part => {
            if (part?.type !== 'file' || typeof part.content !== 'string' || !part.content.trim()) {
                return false;
            }
            if (typeof part.filename !== 'string') return false;
            const ext = part.filename.split('.').pop()?.toLowerCase();
            return !!ext && DOC_ATTACHMENT_EXTENSIONS.has(ext);
        })
        .map(part => ({
            hash: typeof part.contentHash === 'string' ? part.contentHash : null,
            filename: part.filename || 'attachment',
            text: part.content
        }));
    if (entries.length === 0) return;
    if (!Array.isArray(chat.docAttachments)) {
        chat.docAttachments = [];
    }
    const existingHashes = new Set(
        chat.docAttachments.map(entry => entry?.hash).filter(Boolean)
    );
    const additions = entries.filter(entry => !entry.hash || !existingHashes.has(entry.hash));
    if (additions.length === 0) return;
    chat.docAttachments.push(...additions);
    const mergedText = buildDocAttachmentContextText(chat.docAttachments);
    if (mergedText) {
        docAttachmentTextCache.set(chatId, mergedText);
    }
    const contentHashes = new Set();
    collectCidHashesFromContent(content, contentHashes);
    if (contentHashes.size > 0) {
        scheduleDocDataSave(chatId);
        scheduleDocImageUpload(chatId, Array.from(contentHashes));
    }
}

function getDocAttachmentContextForChat(chatId) {
    if (!chatId) return '';
    const cached = docAttachmentTextCache.get(chatId);
    if (cached) return cached;
    const chat = chats?.[chatId];
    if (!chat || !Array.isArray(chat.docAttachments) || chat.docAttachments.length === 0) return '';
    const text = buildDocAttachmentContextText(chat.docAttachments);
    if (text) docAttachmentTextCache.set(chatId, text);
    return text;
}

function clearDocAttachmentCacheForChats(deletedChats) {
    if (!Array.isArray(deletedChats)) return;
    deletedChats.forEach(chat => {
        if (!chat?.id) return;
        docAttachmentTextCache.delete(chat.id);
        docDataSaveSignatures.delete(chat.id);
        if (docDataSaveTimers.has(chat.id)) {
            clearTimeout(docDataSaveTimers.get(chat.id));
            docDataSaveTimers.delete(chat.id);
        }
        docImageUploadCache.delete(chat.id);
        if (docImageUploadTimers.has(chat.id)) {
            clearTimeout(docImageUploadTimers.get(chat.id));
            docImageUploadTimers.delete(chat.id);
        }
    });
}

function hasFileContentInParts(content) {
    if (!Array.isArray(content)) return false;
    return content.some(part =>
        part?.type === 'file' &&
        typeof part.content === 'string' &&
        part.content.trim()
    );
}

function hasRichDocCidInParts(content) {
    if (!Array.isArray(content)) return false;
    return content.some(part =>
        part?.type === 'file' &&
        typeof part.content === 'string' &&
        part.content.includes('cid:')
    );
}

const CID_HASH_REGEX = /cid:([a-f0-9]+)/ig;

function collectCidHashesFromText(text, collector) {
    if (!text || typeof text !== 'string') return;
    CID_HASH_REGEX.lastIndex = 0;
    let match = null;
    while ((match = CID_HASH_REGEX.exec(text)) !== null) {
        if (match[1]) collector.add(match[1]);
    }
}

function collectCidHashesFromContent(content, collector) {
    if (typeof content === 'string') {
        collectCidHashesFromText(content, collector);
        return;
    }
    if (!Array.isArray(content)) return;
    content.forEach(part => {
        if (typeof part === 'string') {
            collectCidHashesFromText(part, collector);
            return;
        }
        if (!part || typeof part !== 'object') return;
        if (typeof part.text === 'string') {
            collectCidHashesFromText(part.text, collector);
        }
        if (typeof part.content === 'string') {
            collectCidHashesFromText(part.content, collector);
        }
    });
}

function hasCidInContent(input) {
    const hashes = new Set();
    if (Array.isArray(input)) {
        input.forEach(item => {
            if (item && typeof item === 'object' && 'content' in item) {
                collectCidHashesFromContent(item.content, hashes);
            } else {
                collectCidHashesFromContent(item, hashes);
            }
        });
    } else {
        collectCidHashesFromContent(input, hashes);
    }
    return hashes.size > 0;
}

function stripImageMarkerText(text) {
    if (!text) return '';
    return text
        .replace(/<PageImage:\s*\d+>/gi, ' ')
        .replace(/!\[[^\]]*\]\(cid:[^)]+\)/gi, ' ')
        .replace(/\s+/g, ' ')
        .trim();
}

function shouldAttachAllImagesForContent(content) {
    if (!content || typeof content !== 'string') return false;
    if (!content.includes('cid:')) return false;
    const cleaned = stripImageMarkerText(content);
    return cleaned.length < 40;
}

function collectAllCidHashesFromText(text) {
    const hashes = new Set();
    collectCidHashesFromText(text, hashes);
    return hashes;
}

function hasPersistedDocContext(chatId) {
    if (!chatId) return false;
    return !!getDocAttachmentContextForChat(chatId);
}

function rebuildDocAttachmentsFromMessages(messages) {
    if (!Array.isArray(messages) || messages.length === 0) return [];
    const entries = [];
    messages.forEach(msg => {
        const parts = Array.isArray(msg?.content) ? msg.content : [];
        parts.forEach(part => {
            if (part?.type !== 'file' || typeof part.content !== 'string' || !part.content.trim()) {
                return;
            }
            if (typeof part.filename !== 'string') return;
            const ext = part.filename.split('.').pop()?.toLowerCase();
            if (!ext || !DOC_ATTACHMENT_EXTENSIONS.has(ext)) return;
            entries.push({
                hash: typeof part.contentHash === 'string' ? part.contentHash : null,
                filename: part.filename || 'attachment',
                text: part.content
            });
        });
    });
    return entries;
}

async function ensureDocAttachmentContextForChat(chatId, chat, allowCleanup = true) {
    if (!chatId || !chat) return;
    const isLoggedIn = !!currentUser;
    const hasAttachments = Array.isArray(chat.docAttachments) && chat.docAttachments.length > 0;
    const cached = docAttachmentTextCache.get(chatId);
    if (hasAttachments && cached) return;

    if (!hasAttachments) {
        if (isLoggedIn) {
            const remoteData = await fetchDocDataFromRemote(chatId);
            if (remoteData && Array.isArray(remoteData.docAttachments) && remoteData.docAttachments.length > 0) {
                chat.docAttachments = remoteData.docAttachments;
                if (Array.isArray(remoteData.cidHashes) && remoteData.cidHashes.length > 0) {
                    scheduleDocImageUpload(chatId, remoteData.cidHashes);
                }
            } else if (allowCleanup) {
                chat.docAttachments = [];
                docAttachmentTextCache.delete(chatId);
                return;
            } else {
                return;
            }
        } else {
            const rebuilt = rebuildDocAttachmentsFromMessages(chat.messages || []);
            if (rebuilt.length > 0) {
                chat.docAttachments = rebuilt;
                scheduleDocDataSave(chatId);
            } else if (allowCleanup) {
                chat.docAttachments = [];
                docAttachmentTextCache.delete(chatId);
                return;
            } else {
                return;
            }
        }
    }

    if (Array.isArray(chat.docAttachments) && chat.docAttachments.length > 0) {
        const mergedText = buildDocAttachmentContextText(chat.docAttachments);
        if (mergedText) {
            docAttachmentTextCache.set(chatId, mergedText);
        } else if (allowCleanup) {
            chat.docAttachments = [];
            docAttachmentTextCache.delete(chatId);
        }
    }
}

function deferDocAttachmentMount(chatId, chat, messagesLoaded) {
    if (!chatId || !chat) return;
    const run = async () => {
        try {
            await ensureDocAttachmentContextForChat(chatId, chat, messagesLoaded);
            if (currentUser && hasCidInChat(chat)) {
                scheduleDocImageUpload(chatId);
            }
        } catch (error) {
            console.warn('Deferred doc attachment mount failed:', error);
        }
    };

    if (typeof requestIdleCallback === 'function') {
        requestIdleCallback(() => {
            run();
        }, { timeout: 1200 });
    } else {
        setTimeout(() => {
            run();
        }, 0);
    }
}

async function waitForDocAttachmentMount(chatId, chat, timeoutMs = 1200) {
    if (!chatId || !chat) return false;
    if (getDocAttachmentContextForChat(chatId)) return true;
    const mountPromise = ensureDocAttachmentContextForChat(chatId, chat, false)
        .then(() => true)
        .catch(() => false);
    const timeoutPromise = new Promise(resolve => {
        setTimeout(() => resolve(false), timeoutMs);
    });
    await Promise.race([mountPromise, timeoutPromise]);
    return !!getDocAttachmentContextForChat(chatId);
}

function collectCidHashesFromChat(chat) {
    const hashes = new Set();
    if (!chat || !Array.isArray(chat.messages)) return hashes;
    chat.messages.forEach(msg => {
        collectCidHashesFromContent(msg?.content, hashes);
    });
    if (Array.isArray(chat.docAttachments)) {
        chat.docAttachments.forEach(entry => {
            if (entry && typeof entry.text === 'string') {
                collectCidHashesFromText(entry.text, hashes);
            }
        });
    }
    return hashes;
}

function hasCidInChat(chat) {
    return collectCidHashesFromChat(chat).size > 0;
}

function collectCidHashesFromChats(chatsMap, excludedChatIds = new Set()) {
    const hashes = new Set();
    if (!chatsMap) return hashes;
    Object.entries(chatsMap).forEach(([chatId, chat]) => {
        if (excludedChatIds.has(chatId)) return;
        const chatHashes = collectCidHashesFromChat(chat);
        chatHashes.forEach(hash => hashes.add(hash));
    });
    return hashes;
}

async function cleanupDocumentImagesForDeletedChats(deletedChats) {
    if (!Array.isArray(deletedChats) || deletedChats.length === 0) return;
    clearDocAttachmentCacheForChats(deletedChats);
    if (currentUser) {
        const ids = deletedChats.map(chat => chat?.id).filter(Boolean);
        deleteDocDataFromRemote(ids);
    }
    const candidateHashes = new Set();
    deletedChats.forEach(chat => {
        const hashes = collectCidHashesFromChat(chat);
        hashes.forEach(hash => candidateHashes.add(hash));
    });
    if (candidateHashes.size === 0) return;

    const remainingHashes = collectCidHashesFromChats(chats);
    const hashesToDelete = [];
    candidateHashes.forEach(hash => {
        if (!remainingHashes.has(hash)) {
            hashesToDelete.push(hash);
        }
    });

    if (hashesToDelete.length === 0) return;
    try {
        await LocalStore.deleteImages(hashesToDelete);
    } catch (error) {
        console.warn('Failed to delete document images after chat removal:', error);
    }
    deletedChats.forEach(chat => {
        if (!chat?.id) return;
        deleteDocImagesFromRemote(chat.id);
    });
}

const TOOL_IMAGE_CALL_REGEX = /fetch_image_details/i;
const GLOBAL_IMAGE_REQUEST_REGEX = /request_global_images/i;
const CID_INLINE_REGEX = /cid:([a-f0-9]{10,})/ig;
const CID_HASH_ONLY_REGEX = /\b[a-f0-9]{40}\b/ig;
const MAX_TOOL_IMAGE_FETCH = 10;

function extractToolCallHashes(text) {
    if (!text || typeof text !== 'string' || !TOOL_IMAGE_CALL_REGEX.test(text)) return [];
    const hashes = new Set();
    CID_INLINE_REGEX.lastIndex = 0;
    let match = null;
    while ((match = CID_INLINE_REGEX.exec(text)) !== null) {
        if (match[1]) hashes.add(match[1]);
    }
    if (hashes.size === 0) {
        CID_HASH_ONLY_REGEX.lastIndex = 0;
        while ((match = CID_HASH_ONLY_REGEX.exec(text)) !== null) {
            if (match[0]) hashes.add(match[0]);
        }
    }
    return Array.from(hashes);
}

function includeAdjacentChunks(relevantChunks, documentIndex, distance = 1) {
    if (!Array.isArray(relevantChunks) || !Array.isArray(documentIndex)) return relevantChunks || [];
    if (relevantChunks.length === 0) return relevantChunks;
    const orderedIds = documentIndex.map(chunk => chunk.chunkId);
    const indexMap = new Map();
    orderedIds.forEach((id, idx) => indexMap.set(id, idx));
    const idSet = new Set(relevantChunks.map(chunk => chunk.chunkId));
    relevantChunks.forEach(chunk => {
        const idx = indexMap.get(chunk.chunkId);
        if (idx === undefined) return;
        for (let offset = 1; offset <= distance; offset += 1) {
            const prevId = orderedIds[idx - offset];
            const nextId = orderedIds[idx + offset];
            if (prevId !== undefined) idSet.add(prevId);
            if (nextId !== undefined) idSet.add(nextId);
        }
    });
    return documentIndex.filter(chunk => idSet.has(chunk.chunkId));
}

async function selectRelevantCidsForQuestion(userMessageText, sourceText) {
    if (!sourceText || !userMessageText) {
        return { relevantText: '', hashes: new Set() };
    }
    if (shouldAttachAllImagesForContent(sourceText)) {
        return { relevantText: '', hashes: collectAllCidHashesFromText(sourceText) };
    }
    const MAX_TOOL_TEXT = 12000;
    const truncatedSource = sourceText.length > MAX_TOOL_TEXT
        ? `${sourceText.slice(0, MAX_TOOL_TEXT)}\n\n[Content truncated]`
        : sourceText;
    const toolPrompt = `You are selecting relevant document passages and image references for a user's question. Return JSON only.
{"relevant_text":"...","cids":["cid:hash1","cid:hash2"]} 
Rules:
- relevant_text must be quotes from the provided content (no invention).
- Do NOT include markdown image syntax or backticks in relevant_text.
- Escape newlines as \\n and quotes as \\" inside relevant_text.
- cids should include only those mentioned in relevant_text, prefer up to ${MAX_TOOL_IMAGE_FETCH}.
- If no image is needed, return an empty cids array.

User question: "${userMessageText}"

Content:
${truncatedSource}`;

    try {
        const toolResult = await callAISynchronously(toolPrompt, 'gemini-2.5-flash-lite', false);
        const { relevantText, cidList } = parseDetailQueryToolResult(toolResult);
        const hashes = new Set();
        const cids = cidList.length > 0 ? cidList : extractToolCallHashes(toolResult);
        cids.forEach((cid) => {
            if (typeof cid !== 'string') return;
            const match = cid.match(/cid:([a-f0-9]{10,})/i);
            if (match && match[1]) hashes.add(match[1].toLowerCase());
            if (!match) {
                const raw = cid.trim();
                if (/^[a-f0-9]{40}$/i.test(raw)) hashes.add(raw.toLowerCase());
            }
        });
        return { relevantText: relevantText || '', hashes };
    } catch (error) {
        console.warn('Global image selection failed:', error);
        return { relevantText: '', hashes: new Set() };
    }
}

async function resolveRelevantCidSelection({
    userMessageText,
    sourceText,
    chatId,
    userContent,
    includeUserImagesForTool = false
}) {
    const emptyResult = { relevantText: '', hashes: [], selectedCidImages: [], inlineImages: [] };
    if (!userMessageText || !sourceText) return emptyResult;
    try {
        const { relevantText, hashes } = await selectRelevantCidsForQuestion(userMessageText, sourceText);
        const hashList = hashes && hashes.size > 0 ? Array.from(hashes) : [];
        const selectedCidImages = hashList.length > 0
            ? await buildImagePartsFromCids(hashList, chatId)
            : [];
        const toolImageParts = [];
        if (includeUserImagesForTool && Array.isArray(userContent)) {
            toolImageParts.push(...userContent);
        }
        if (selectedCidImages.length > 0) {
            toolImageParts.push(...selectedCidImages);
        }
        const inlineImages = toolImageParts.length > 0
            ? extractInlineImagesFromContent(toolImageParts)
            : [];
        return { relevantText: relevantText || '', hashes: hashList, selectedCidImages, inlineImages };
    } catch (error) {
        console.warn('Relevant CID selection failed:', error);
        return emptyResult;
    }
}

function tryParseJsonObject(rawText) {
    if (typeof rawText !== 'string') return null;
    let text = rawText.trim();
    if (text.startsWith('```')) {
        text = text.replace(/^```[a-zA-Z]*\s*/m, '').replace(/\s*```$/m, '').trim();
    }
    const start = text.indexOf('{');
    const end = text.lastIndexOf('}');
    if (start === -1 || end === -1 || end <= start) return null;
    const candidate = text.slice(start, end + 1);
    let quoteCount = 0;
    let escaped = false;
    for (let i = 0; i < candidate.length; i += 1) {
        const ch = candidate[i];
        if (escaped) {
            escaped = false;
            continue;
        }
        if (ch === '\\') {
            escaped = true;
            continue;
        }
        if (ch === '"') quoteCount += 1;
    }
    if (quoteCount % 2 !== 0) return null;
    try {
        return JSON.parse(candidate);
    } catch (_) {
        return null;
    }
}

function parseDetailQueryToolResult(rawText) {
    const parsed = tryParseJsonObject(rawText);
    const relevantText = parsed && typeof parsed.relevant_text === 'string'
        ? parsed.relevant_text.trim()
        : '';
    const cidList = Array.isArray(parsed?.cids) ? parsed.cids : [];
    return { relevantText, cidList };
}

async function buildImagePartsFromCids(hashes, chatId = null) {
    if (!Array.isArray(hashes) || hashes.length === 0) return [];
    const parts = [];
    const limit = Math.min(hashes.length, MAX_TOOL_IMAGE_FETCH);
    for (let i = 0; i < limit; i += 1) {
        const hash = hashes[i];
        try {
            const blob = await LocalStore.getImage(hash, chatId);
            if (!blob) continue;
            const base64 = await LocalStore.blobToBase64(blob);
            if (!base64) continue;
            parts.push({
                type: 'image_url',
                image_url: { url: `data:${blob.type || 'image/png'};base64,${base64}` }
            });
        } catch (_) {
            // Skip missing or failed images.
        }
    }
    return parts;
}

function escapeForRegExp(text) {
    return String(text || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function collectMessageTextContent(message) {
    if (!message) return '';
    const content = message.content;
    if (typeof content === 'string') return content;
    if (Array.isArray(content)) {
        return content
            .map((part) => {
                if (typeof part === 'string') return part;
                if (part?.type === 'text' && typeof part.text === 'string') return part.text;
                return '';
            })
            .filter(Boolean)
            .join(' ');
    }
    if (content && typeof content === 'object') {
        if (typeof content.content === 'string') return content.content;
        if (Array.isArray(content.content)) {
            return content.content
                .map((part) => (part?.type === 'text' && typeof part.text === 'string' ? part.text : ''))
                .filter(Boolean)
                .join(' ');
        }
    }
    return '';
}

function collectAssistantImageParts(message) {
    if (!message || typeof message !== 'object') return [];
    const fromMessage = streamImageRuntime.normalizeStreamImageParts(message.image_parts || message.image_urls || []);
    if (fromMessage.length > 0) return fromMessage;

    const content = message.content;
    if (Array.isArray(content)) {
        return streamImageRuntime.normalizeStreamImageParts(content);
    }
    if (content && typeof content === 'object') {
        return streamImageRuntime.normalizeStreamImageParts(content.image_parts || content.image_urls || []);
    }
    return [];
}

function extractAssistantImageDescription(message) {
    if (!message || typeof message !== 'object') return '';
    if (typeof message.image_description === 'string' && message.image_description.trim()) {
        return message.image_description.trim();
    }
    const rawText = collectMessageTextContent(message);
    if (!rawText) return '';

    const label = getToastMessage('ui.imageDescription');
    const plainText = rawText
        .replace(/<[^>]+>/g, ' ')
        .replace(/\*\*/g, '')
        .replace(/\s+/g, ' ')
        .trim();
    const descRe = new RegExp(`${escapeForRegExp(label)}\\s*[：:]\\s*(.+)$`, 'i');
    const match = plainText.match(descRe);
    if (match && match[1]) {
        return match[1].trim();
    }
    return '';
}

class IntentAnalyzer {
    constructor() {
        this.currentMessageIntentResult = null;
        this.currentMessageGtAnalysisResult = null;
        this._creativeKeywords = null;
        this._roleplayKeywords = null;
        this._classicalKeywords = null;
    }

    getCreativeKeywords() {
        if (!this._creativeKeywords) {
            this._creativeKeywords = [
                getToastMessage('intent.keywords.creative.writeOne'),
                getToastMessage('intent.keywords.creative.writeOneStory'),
                getToastMessage('intent.keywords.creative.write'),
                getToastMessage('intent.keywords.creative.fanfic'),
                getToastMessage('intent.keywords.creative.fanwork'),
                getToastMessage('intent.keywords.creative.story'),
                getToastMessage('intent.keywords.creative.novel'),
                getToastMessage('intent.keywords.creative.create'),
                getToastMessage('intent.keywords.creative.createOne'),
                'write a story', 'fanfic', 'create a story', 'tell me a story'
            ];
        }
        return this._creativeKeywords;
    }

    getRoleplayKeywords() {
        if (!this._roleplayKeywords) {
            this._roleplayKeywords = [
                getToastMessage('intent.keywords.roleplay.roleplay'),
                getToastMessage('intent.keywords.roleplay.play'),
                getToastMessage('intent.keywords.roleplay.playRole'),
                getToastMessage('intent.keywords.roleplay.roleSetting'),
                getToastMessage('intent.keywords.roleplay.character'),
                getToastMessage('intent.keywords.roleplay.createRole'),
                'roleplay', 'rp', 'character roleplay', 'role play', 'play a role'
            ];
        }
        return this._roleplayKeywords;
    }

    getClassicalKeywords() {
        if (!this._classicalKeywords) {
            this._classicalKeywords = [
                getToastMessage('intent.keywords.classical.ancientText'),
                getToastMessage('intent.keywords.classical.classicalChinese'),
                getToastMessage('intent.keywords.classical.ancientPoetry'),
                getToastMessage('intent.keywords.classical.poetry'),
                getToastMessage('intent.keywords.classical.historicalText'),
                getToastMessage('intent.keywords.classical.classicalLiterature'),
                getToastMessage('intent.keywords.classical.ancient'),
                getToastMessage('intent.keywords.classical.translateAncient'),
                getToastMessage('intent.keywords.classical.explainPoetry'),
                getToastMessage('intent.keywords.classical.translateClassical'),
                'classical chinese', 'ancient text', 'poetry'
            ];
        }
        return this._classicalKeywords;
    }


    reset() {
        this.currentMessageIntentResult = null;
        this.currentMessageGtAnalysisResult = null;
    }

    clearKeywordCache() {
        this._creativeKeywords = null;
        this._roleplayKeywords = null;
        this._classicalKeywords = null;
    }

    containsCreativeKeywords(text) {
        const lowerText = text.toLowerCase();
        return this.getCreativeKeywords().some(kw => lowerText.includes(kw.toLowerCase()));
    }

    containsRoleplayKeywords(text) {
        const lowerText = text.toLowerCase();
        return this.getRoleplayKeywords().some(kw => lowerText.includes(kw.toLowerCase()));
    }

    containsClassicalChineseKeywords(text) {
        const lowerText = text.toLowerCase();
        return this.getClassicalKeywords().some(kw => lowerText.includes(kw.toLowerCase()));
    }

    shouldTriggerIntentAnalysis(userMessageText) {
        if (this.shouldDetectClassicalChinese(userMessageText)) {
            return true;
        }

        if (userMessageText.length >= 20 && this.shouldDetectRoleplay(userMessageText)) {
            return true;
        }

        if (userMessageText.length >= 20 && this.shouldDetectTextCreation(userMessageText)) {
            return true;
        }

        return false;
    }

    shouldDetectClassicalChinese(userMessageText) {
        return this.containsClassicalChineseKeywords(userMessageText) &&
            (userMessageText.includes(getToastMessage('intent.keywords.classical.translate')) ||
                userMessageText.includes(getToastMessage('intent.keywords.classical.explain')) ||
                userMessageText.includes(getToastMessage('intent.keywords.classical.analyze')) ||
                userMessageText.includes(getToastMessage('intent.keywords.classical.whatMean')) ||
                userMessageText.includes(getToastMessage('intent.keywords.classical.meaning')));
    }

    shouldDetectRoleplay(userMessageText) {
        // 关键词触发
        if (this.containsRoleplayKeywords(userMessageText)) {
            return true;
        }
        if (userMessageText.length >= 40 &&
            (userMessageText.includes(getToastMessage('intent.keywords.roleplay.character')) ||
                userMessageText.includes(getToastMessage('intent.keywords.roleplay.play')) ||
                userMessageText.includes(getToastMessage('intent.keywords.roleplay.character')))) {
            return true;
        }
        return false;
    }

    shouldDetectTextCreation(userMessageText) {
        // 关键词触发
        if (this.containsCreativeKeywords(userMessageText)) {
            return true;
        }
        // 长消息+创作词汇触发
        if (userMessageText.length >= 40 &&
            (userMessageText.includes(getToastMessage('intent.keywords.creative.write')) ||
                userMessageText.includes(getToastMessage('intent.keywords.creative.create')) ||
                userMessageText.includes(getToastMessage('intent.keywords.creative.story')) ||
                userMessageText.includes(getToastMessage('intent.keywords.creative.novel')) ||
                userMessageText.includes(getToastMessage('intent.keywords.creative.fanfic')) ||
                userMessageText.includes(getToastMessage('intent.keywords.creative.fanwork')))) {
            return true;
        }
        return false;
    }

    async analyzeUserIntent(userMessageText, conversationHistory = []) {
        if (this.currentMessageIntentResult) {
            return this.currentMessageIntentResult;
        }

        const recentHistory = conversationHistory.slice(-6).map(msg => {
            let content = '';

            const imageParts = collectAssistantImageParts(msg);
            if (msg.role === 'assistant' && imageParts.length > 0) {
                const desc = extractAssistantImageDescription(msg) || getToastMessage('ui.unknown');
                content = `[${getToastMessage('ui.imageGenerated')}，${getToastMessage('ui.description')}: ${desc}]`;
            } else {
                content = collectMessageTextContent(msg);
            }
            return `${msg.role}: ${content.substring(0, 200)}`;
        }).join('\n');

        const intentAnalysisPrompt = `Analyze the user's intent and classify it into one of these categories: "CLASSICAL_CHINESE_ANALYSIS", "ROLEPLAY_CREATIVE", or "GENERAL_QUERY".

        Rules:
        1. Classical Chinese: classical Chinese, ancient poetry, or historical texts -> "CLASSICAL_CHINESE_ANALYSIS"
        2. Creative Writing: roleplay, storytelling, story creation, character scenarios -> "ROLEPLAY_CREATIVE"
        3. Default: all other cases -> "GENERAL_QUERY"

        Examples:
        - "请赏析《静夜思》" -> "CLASSICAL_CHINESE_ANALYSIS"
        - "Write a story about..." -> "ROLEPLAY_CREATIVE"
        - "What's the weather?" -> "GENERAL_QUERY"

        User Message (first 500 chars): "${userMessageText.substring(0, 500)}"

        Return only JSON:
        {"intent": "one_of_the_intents", "confidence": 0.9}`

        try {
            const response = await callAISynchronously(intentAnalysisPrompt, 'gemini-2.5-flash-lite', false);
            const result = safeJsonParse(response);

            if (result && result.intent && ['CLASSICAL_CHINESE_ANALYSIS', 'ROLEPLAY_CREATIVE', 'GENERAL_QUERY'].includes(result.intent)) {
                console.log(`${getToastMessage('console.aiIntentAnalysisResult')}:`, {
                    mode: result.intent
                });
                const finalResult = {
                    intent: result.intent,
                    confidence: result.confidence || 0.7,
                    reasoning: result.reasoning || ''
                };
                this.currentMessageIntentResult = finalResult;
                return finalResult;
            }
            console.warn(getToastMessage('console.aiIntentAnalysisFailed'));
            const fallbackResult = this.fallbackIntentDetection(userMessageText);
            this.currentMessageIntentResult = fallbackResult;
            return fallbackResult;

        } catch (error) {
            console.error(`${getToastMessage('console.intentAnalysisFailed')}:`, error);
            const fallbackResult = this.fallbackIntentDetection(userMessageText);
            this.currentMessageIntentResult = fallbackResult;
            return fallbackResult;
        }
    }

    async analyzeGtAnalysisIntent(userMessageText, conversationHistory = []) {
        if (this.currentMessageGtAnalysisResult) {
            return this.currentMessageGtAnalysisResult;
        }

        if (!hasDocAttachmentsInHistory(conversationHistory)) {
            return null;
        }

        const trimmedQuery = (userMessageText || '').trim();
        const intentPrompt = `Classify a request about an uploaded doc:
        - "GT_ANALYSIS": overall/broad analysis.
        - "DETAIL_QUERY": specific section/page/figure/table/diagram/formula/“this part”.
        If unrelated or unsure -> "GT_ANALYSIS" and needs_images=false.

        Return ONLY JSON: {"intent":"GT_ANALYSIS|DETAIL_QUERY","needs_images":true|false,"confidence":0.0,"reasoning":""}

        User request: "${trimmedQuery.substring(0, 800)}"`;

        try {
            const response = await callAISynchronously(intentPrompt, 'gemini-2.5-flash-lite', false);
            const parsed = safeJsonParse(response, null);
            const intent = parsed && typeof parsed.intent === 'string'
                ? parsed.intent.trim().toUpperCase()
                : '';
            const needsImages = parsed && typeof parsed.needs_images === 'boolean'
                ? parsed.needs_images
                : (intent === 'DETAIL_QUERY');
            const confidence = parsed && typeof parsed.confidence === 'number'
                ? parsed.confidence
                : 0.7;
            const reasoning = parsed && typeof parsed.reasoning === 'string'
                ? parsed.reasoning
                : '';

            if (intent === 'GT_ANALYSIS' || intent === 'DETAIL_QUERY') {
                const result = {
                    intent,
                    needsImages,
                    confidence,
                    reasoning
                };
                console.log(`${getToastMessage('console.aiIntentAnalysisResult')}: ${intent}`);
                this.currentMessageGtAnalysisResult = result;
                return result;
            }
        } catch (error) {
            console.error('GT analysis intent detection failed:', error);
        }

        const fallbackResult = {
            intent: 'GT_ANALYSIS',
            needsImages: false,
            confidence: 0.6,
            reasoning: ''
        };
        console.log(`${getToastMessage('console.aiIntentAnalysisResult')}: ${fallbackResult.intent}`);
        this.currentMessageGtAnalysisResult = fallbackResult;
        return fallbackResult;
    }

    fallbackIntentDetection(userMessageText) {
        if (this.containsRoleplayKeywords(userMessageText)) {
            return { intent: 'ROLEPLAY_CREATIVE', confidence: 0.7, reasoning: getToastMessage('ui.roleplayKeywordMatch') };
        }

        if (this.containsCreativeKeywords(userMessageText)) {
            return { intent: 'ROLEPLAY_CREATIVE', confidence: 0.7, reasoning: getToastMessage('ui.creativeKeywordMatch') };
        }

        if (this.containsClassicalChineseKeywords(userMessageText)) {
            return { intent: 'CLASSICAL_CHINESE_ANALYSIS', confidence: 0.7, reasoning: getToastMessage('ui.classicalKeywordMatch') };
        }
        return { intent: 'GENERAL_QUERY', confidence: 0.9, reasoning: getToastMessage('ui.defaultTextResponse') };
    }

    async performUnifiedIntentAnalysis(userMessageText, conversationHistory = [], options = {}) {
        const needsAIAnalysis = this.shouldTriggerIntentAnalysis(userMessageText);
        const enableGtAnalysis = options?.enableGtAnalysis !== false;

        let intentResult = null;
        if (needsAIAnalysis) {
            intentResult = await this.analyzeUserIntent(userMessageText, conversationHistory);
        }

        const result = {
            shouldGenerateImage: false,
            shouldUseClassicalChinesePrompt: false,
            shouldUseRoleplayPrompt: false,
            shouldUseCreativePrompt: false,
            intentResult
        };

        if (enableGtAnalysis) {
            const gtAnalysisResult = await this.analyzeGtAnalysisIntent(userMessageText, conversationHistory);
            if (gtAnalysisResult) {
                result.gtAnalysis = gtAnalysisResult;
            }
        }

        if (this.shouldDetectClassicalChinese(userMessageText)) {
            result.shouldUseClassicalChinesePrompt = intentResult ? intentResult.intent === 'CLASSICAL_CHINESE_ANALYSIS' : true;
        }

        if (this.shouldDetectRoleplay(userMessageText)) {
            result.shouldUseRoleplayPrompt = intentResult ? intentResult.intent === 'ROLEPLAY_CREATIVE' : true;
        }

        if (this.shouldDetectTextCreation(userMessageText)) {
            result.shouldUseCreativePrompt = intentResult ? intentResult.intent === 'ROLEPLAY_CREATIVE' : true;
        }

        return result;
    }

    async analyzeIntentWithAttachmentsForImageMode(userContent, userMessageText) {
        const inlineImages = extractInlineImagesFromContent(userContent);
        const fileParts = userContent.filter(part =>
            part?.type === 'file' && typeof part.content === 'string'
        );

        const allowedIntents = [
            'IMAGE_GENERATION',
            'GENERAL_QUERY'
        ];
        const MAX_FILES = 3;
        const MAX_CHARS_PER_FILE = 2000;
        const fileSummaries = fileParts.slice(0, MAX_FILES).map((part, index) => {
            const rawText = part.content || '';
            const trimmed = rawText.trim();
            const truncated = trimmed.length > MAX_CHARS_PER_FILE
                ? `${trimmed.slice(0, MAX_CHARS_PER_FILE)}\n[Content truncated]`
                : trimmed;
            const filename = part.filename || `file_${index + 1}`;
            return `File ${index + 1}: ${filename}\n${truncated}`;
        });

        const prompt = `Intent analysis (IMAGE MODE).
        Decide IMAGE_GENERATION vs GENERAL_QUERY.
        If IMAGE_GENERATION: extract detailed visual intent (subjects, attributes, style, setting, composition, lighting) from request+attachments; no inventions; include image_summary if images exist. If images contain readable text, include key OCR text in image_text (short, essential only) and use it for intent.
        If GENERAL_QUERY: return a concise combined_request for normal chat.
        Return ONLY JSON: {"combined_request":"detailed sentence","intent":"IMAGE_GENERATION|GENERAL_QUERY","confidence":0.0,"reasoning":"","image_summary":"","image_text":""}
        Rules: Use English for combined_request, image_summary, and image_text; be detailed for image generation; avoid sexual content/minors/unsafe content. Do NOT include unescaped double quotes in any value; replace them or paraphrase.

        User request: "${userMessageText || ''}"
        Attachments: ${fileSummaries.length ? fileSummaries.join(' | ') : '[No file text provided]'}
        `;

        try {
            const summary = await callAISynchronously(prompt, 'gemini-2.5-flash-lite', false, inlineImages);
            const parsed = safeJsonParse(summary, null);
            const combined = parsed && typeof parsed.combined_request === 'string'
                ? parsed.combined_request.trim()
                : null;
            const intent = parsed && typeof parsed.intent === 'string'
                ? parsed.intent.trim()
                : null;
            const confidence = parsed && typeof parsed.confidence === 'number'
                ? parsed.confidence
                : null;
            const reasoning = parsed && typeof parsed.reasoning === 'string'
                ? parsed.reasoning
                : '';
            const imageSummary = parsed && typeof parsed.image_summary === 'string'
                ? parsed.image_summary.trim()
                : '';
            const imageText = parsed && typeof parsed.image_text === 'string'
                ? parsed.image_text.trim()
                : '';
            if (!combined || !intent || !allowedIntents.includes(intent)) {
                return { combinedUserMessageText: combined || null, intentResult: null, imageSummary: '', imageText: '' };
            }
            return {
                combinedUserMessageText: combined,
                intentResult: {
                    intent,
                    confidence: typeof confidence === 'number' ? confidence : 0.7,
                    reasoning
                },
                imageSummary,
                imageText
            };
        } catch (error) {
            return null;
        }
    }

    async analyzeImageModeIntent(userContent, userMessageText, hasImageAttachments, hasFileAttachments) {
        const attachmentAnalysis = await this.analyzeIntentWithAttachmentsForImageMode(userContent, userMessageText);
        let combinedUserMessageText = attachmentAnalysis?.combinedUserMessageText || userMessageText;
        if (attachmentAnalysis?.intentResult) {
            console.log(`${getToastMessage('console.aiIntentAnalysisResult')}:`, {
                mode: attachmentAnalysis.intentResult.intent
            });
            if (attachmentAnalysis.intentResult.intent === 'IMAGE_GENERATION') {
                const parts = [];
                const imageSummary = attachmentAnalysis.imageSummary;
                const imageText = attachmentAnalysis.imageText;
                if (imageSummary) {
                    parts.push(imageSummary);
                }
                if (imageText) {
                    parts.push(`Image text: ${imageText}`);
                }
                if (userMessageText) {
                    parts.push(`User request: ${userMessageText}`);
                }
                if (parts.length > 0) {
                    combinedUserMessageText = parts.join('\n').trim();
                }
            }
            return {
                combinedUserMessageText,
                intentAnalysis: {
                    shouldGenerateImage: attachmentAnalysis.intentResult.intent === 'IMAGE_GENERATION',
                    shouldSuggestImageMode: false,
                    shouldUseClassicalChinesePrompt: false,
                    shouldUseRoleplayPrompt: false,
                    shouldUseCreativePrompt: false,
                    intentResult: attachmentAnalysis.intentResult
                }
            };
        }

        const fallbackIntentResult = {
            intent: 'GENERAL_QUERY',
            confidence: 0.7,
            reasoning: getToastMessage('ui.defaultTextResponse')
        };
        console.log(`${getToastMessage('console.intentAnalysisFailed')}:`, {
            mode: fallbackIntentResult.intent
        });
        return {
            combinedUserMessageText,
            intentAnalysis: {
                shouldGenerateImage: false,
                shouldSuggestImageMode: false,
                shouldUseClassicalChinesePrompt: false,
                shouldUseRoleplayPrompt: false,
                shouldUseCreativePrompt: false,
                intentResult: fallbackIntentResult
            }
        };
    }
}

const intentAnalyzer = new IntentAnalyzer();

async function performUnifiedIntentAnalysis(userMessageText, conversationHistory = [], options = {}) {
    return await intentAnalyzer.performUnifiedIntentAnalysis(userMessageText, conversationHistory, options);
}

function extractImagePrompt(userMessageText) {
    let prompt = userMessageText;
    const fillerWords = [getToastMessage('ui.please'), getToastMessage('ui.helpMe'), getToastMessage('ui.giveMe'), getToastMessage('ui.iWant'), getToastMessage('ui.iNeed'), 'please', 'help me', 'i want', 'i need'];
    fillerWords.forEach(word => {
        prompt = prompt.replace(new RegExp(`^${word}`, 'gi'), '').trim();
    });

    if (prompt.length < 5) {
        prompt = userMessageText;
    }
    return prompt || getToastMessage('ui.beautifulImage');
}

function extractInlineImagesFromContent(userContent) {
    if (!Array.isArray(userContent)) return [];
    const images = [];
    userContent.forEach(part => {
        const url = part?.image_url?.url;
        if (!url || typeof url !== 'string') return;
        const match = url.match(/^data:(image\/[a-zA-Z0-9.+-]+);base64,(.+)$/);
        if (match && match[2]) {
            images.push({ mimeType: match[1], data: match[2] });
        }
    });
    return images;
}


async function generateCombinedImagePrompt(userMessageText, conversationHistory, intent, imageDescription = null) {
    const userPrompt = extractImagePrompt(userMessageText);
    const sourcePrompt = imageDescription
        ? `${imageDescription}\n${userPrompt}`
        : userPrompt;

    if (intent === 'IMAGE_GENERATION') {
        const promptForAI = `Act as a strict AI image prompt builder. Rewrite the user's description into a single detailed English prompt for Midjourney/Stable Diffusion. Maximize clarity, quality, and style. Return ONLY the final prompt, nothing else.
        User's description: "${sourcePrompt}"`;

        try {
            const englishPrompt = await callAISynchronously(promptForAI, 'gemini-2.5-flash-lite');

            return {
                original: userPrompt,
                english: englishPrompt || sourcePrompt,
                localizedDescription: null
            };
        } catch (error) {
            console.error(`${getToastMessage('console.firstPromptOptimizationFailed')}:`, error);
            return {
                original: userPrompt,
                english: sourcePrompt,
                localizedDescription: null
            };
        }

    } else if (intent === 'image_modification') {
        let originalPrompt = 'a beautiful picture';

        for (let i = conversationHistory.length - 1; i >= 0; i--) {
            const msg = conversationHistory[i];

            if (msg.role !== 'assistant') continue;
            const imageParts = collectAssistantImageParts(msg);
            if (imageParts.length === 0) continue;

            const desc = extractAssistantImageDescription(msg);
            if (desc) {
                try {
                    const reversePrompt = `Convert the following image description back to a detailed English prompt suitable for AI image generation. Description: ${desc}`;
                    originalPrompt = await callAISynchronously(reversePrompt, 'gemini-2.5-flash-lite');
                } catch (e) {
                    originalPrompt = desc;
                }
                break;
            }
        }

        const promptForAI = `Act as a strict AI image prompt builder. Rewrite a single English prompt that merges the original idea and the user's edits. Keep it complete, descriptive, and ready for Midjourney/SD. Output ONLY the final prompt.
        Original prompt: "${originalPrompt}"
        User's modification request: "${userMessageText}"`;

        const targetLang = getCurrentLanguage() || currentUser?.language || 'en';
        const localizedDescriptionPrompt = `Write one concise 10-20 word image description in ${targetLang}. Output ONLY the final description sentence.
        Do not include labels or metadata such as "Request:", "User request:", "Original image info:", or "English prompt:".
        Focus on visual content only (subjects, style, lighting, setting).
        Context:
        - Original image info: "${originalPrompt}"
        - User modification request: "${userMessageText}"`;

        try {
            const newEnglishPrompt = await callAISynchronously(promptForAI, 'gemini-2.5-flash-lite');
            const localizedDescriptionRaw = await callAISynchronously(localizedDescriptionPrompt, 'gemini-2.5-flash-lite');
            const localizedDescription = await translateToUserLanguage(
                (localizedDescriptionRaw || userMessageText || '').toString().trim().replace(/^["']|["']$/g, '')
            );

            return {
                original: userMessageText,
                english: newEnglishPrompt || `${originalPrompt}, ${userMessageText}`,
                localizedDescription: localizedDescription || userMessageText
            };
        } catch (error) {
            return {
                original: userMessageText,
                english: `${originalPrompt}, ${userMessageText}`,
                localizedDescription: await translateToUserLanguage(userMessageText)
            };
        }
    }
    return {
        original: userMessageText,
        english: userMessageText,
        localizedDescription: await translateToUserLanguage(userMessageText)
    };
}

async function handleImageGeneration(userContent, promptObject, options = {}) {
    const { existingAssistantElement = null } = options;
    const englishPrompt = promptObject.english;

        if (!currentChatId) await startNewChat(true);
    const chatIdForRequest = currentChatId;
    const imageUsageBase = Number(currentUserUsage?.imagesCount) || 0;
    const imageUsageToken = `img_${chatIdForRequest}_${Date.now()}`;

    let userMessageToSave = null;
    if (!existingAssistantElement) {
        userMessageToSave = createChatMessage('user', userContent);
        chats[chatIdForRequest].messages.push(userMessageToSave);
        appendMessage('user', userContent);

        // 立即保存用户消息到本地数据库
        try {
            if (!currentUser) {
                await saveChatsToDB('guest', chats);
            } else {
                await saveChatsToDB(currentUser.id, chats);
            }
        } catch (error) {
            console.error('Failed to save user message to database:', error);
        }
    }

    let assistantMessageElement;
    if (existingAssistantElement) {
        assistantMessageElement = existingAssistantElement;
    } else {
        assistantMessageElement = appendMessage('assistant', '');
    }

    const contentDiv = assistantMessageElement.querySelector('.content');

    contentDiv.innerHTML = `
        <div class="thinking-indicator-new">
            <svg class="spinner" viewBox="0 0 50 50">
                <circle class="path" cx="25" cy="25" r="20" fill="none" stroke-width="5"></circle>
            </svg>
            <span>${getToastMessage('ui.generationMayTake1to2Minutes')}</span>
        </div>`;

    let assistantMessage = createChatMessage(
        'assistant',
        `[${getToastMessage('ui.generationMayTake1to2Minutes')}, ${getToastMessage('ui.description')}: ${englishPrompt}]`
    );

    chats[chatIdForRequest].messages.push(assistantMessage);

    return new Promise((resolve) => {
        const baseUrl = isNativeApp ? API_BASE_URL : '';
        const searchParams = new URLSearchParams({ prompt: englishPrompt });
        if (sessionId) {
            searchParams.set('sessionId', sessionId);
        }

        const loadImage = async () => {
            let previewDescription = String(promptObject.localizedDescription || '').trim();
            if (!previewDescription) {
                previewDescription = String(
                    await translateToUserLanguage(promptObject.original || '', { fallbackToOriginal: false }) || ''
                ).trim();
            }
            if (!previewDescription) {
                previewDescription = String(promptObject.english || '').trim();
            }
            if (!previewDescription) {
                previewDescription = getToastMessage('ui.imageGenerated');
            }
            const previewText = `${getToastMessage('ui.generatedImageForYou')}\n\n**${getToastMessage('ui.imageDescription')}：** ${previewDescription}`;
            if (previewText.trim()) {
                searchParams.set('previewText', previewText);
            }

            const params = new URLSearchParams(searchParams);
            params.set('stream', '1');
            const headers = {};
            let visitorId = null;
            if (!sessionId) {
                visitorId = await getGuestVisitorId();
                if (visitorId) {
                    params.set('visitorId', visitorId);
                    headers['X-Visitor-ID'] = visitorId;
                }
            } else {
                headers['X-Session-ID'] = sessionId;
            }
            const imageUrl = `${baseUrl}/api/image-proxy?${params.toString()}`;

            const fetchWithRetry = async (attempt = 1) => {
                const controller = new AbortController();
                const timeoutMs = 90000;
                const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
                const timestamp = Date.now();
                activeResponses.set(chatIdForRequest, { controller, timestamp });

                try {
                    const response = await fetch(imageUrl, {
                        signal: controller.signal,
                        headers,
                        cache: 'no-store',
                        mode: 'cors'
                    });
                    clearTimeout(timeoutId);
                    if (!response.ok) {
                        if (response.status === 429) {
                            showUsageLimitModal();
                            throw new Error('API usage limit reached');
                        }
                        const mappedMessage = getModelErrorMessage(response.status);
                        throw new Error(mappedMessage || `${getToastMessage('errors.serverError')}: ${response.status}`);
                    }
                    const contentType = response.headers.get('content-type') || '';
                    if (contentType.includes('text/event-stream')) {
                        const streamResult = await streamImageRuntime.processStreamedResponse(response, contentDiv, {
                            provisionalImageLayout: [{ image_id: 'img_1', placement: 'after_paragraph:1' }],
                            usePendingImagePlaceholder: true
                        });
                        const parts = streamImageRuntime.normalizeStreamImageParts(streamResult?.streamImageParts || []);
                        const streamImageUrl = parts[0]?.image_url?.url || '';
                        if (!streamImageUrl) {
                            throw new Error('No image url returned from stream.');
                        }
                        return {
                            imageUrl: streamImageUrl,
                            streamedText: (streamResult?.fullResponse || '').trim(),
                            streamedImageLayout: streamImageRuntime.normalizeStreamImageLayout(streamResult?.streamImageLayout || [])
                        };
                    }

                    let finalImageUrl = null;
                    if (contentType.includes('application/json')) {
                        const data = await response.json();
                        finalImageUrl = data?.url;
                        if (!finalImageUrl) {
                            throw new Error('No image url returned from server.');
                        }
                    } else if (contentType.startsWith('image/')) {
                        const blob = await response.blob();
                        finalImageUrl = URL.createObjectURL(blob);
                    } else {
                        throw new Error('Invalid content type received from server.');
                    }
                    return { imageUrl: finalImageUrl, streamedText: '', streamedImageLayout: [] };
                } catch (error) {
                    clearTimeout(timeoutId);
                    activeResponses.delete(chatIdForRequest);
                    if (attempt < 2) {
                        console.warn(`Image fetch attempt ${attempt} failed, retrying...`, error);
                        await sleep(1500);
                        return fetchWithRetry(attempt + 1);
                    }
                    throw error;
                }
            };

            let finalImageUrl = null;
            try {
                const generated = await fetchWithRetry();
                finalImageUrl = generated?.imageUrl || '';
                const { displayUrl, originalUrl } = await ensureDisplayableImageUrl(finalImageUrl, headers);

                let localizedDescription = promptObject.localizedDescription || null;
                if (!localizedDescription) {
                    try {
                        const targetLang = (currentUser?.language || localStorage.getItem('selectedLanguage') || getCurrentLanguage() || 'en').trim();
                        const localizedDescriptionPrompt = `Write one concise 15-30 word image description in ${targetLang}. Output ONLY the final description sentence.
Do not include labels or metadata such as "Request:", "User request:", or "English prompt:".
Focus on visual content only (subjects, style, lighting, setting).
                        Context:
- User request: "${promptObject.original}"
- English prompt: "${englishPrompt}"`;
                        const localizedDescriptionRaw = await callAISynchronously(localizedDescriptionPrompt, 'gemini-2.5-flash-lite');
                        localizedDescription = await translateToUserLanguage(
                            (localizedDescriptionRaw || promptObject.original || '').toString().trim().replace(/^["']|["']$/g, ''),
                            { fallbackToOriginal: false }
                        );
                    } catch (e) {
                        localizedDescription = await translateToUserLanguage(promptObject.original, { fallbackToOriginal: false });
                    }
                }
                localizedDescription = String(localizedDescription || '').trim();
                if (!localizedDescription) {
                    localizedDescription = String(
                        await translateToUserLanguage(promptObject.original, { fallbackToOriginal: false }) || ''
                    ).trim();
                }
                if (!localizedDescription) {
                    localizedDescription = String(promptObject.english || '').trim();
                }
                if (!localizedDescription) {
                    localizedDescription = getToastMessage('ui.imageGenerated');
                }

                const imageParts = streamImageRuntime.normalizeStreamImageParts([{
                    type: 'image_url',
                    image_url: { url: displayUrl || originalUrl }
                }]);
                const imageLayoutFromStream = streamImageRuntime.normalizeStreamImageLayout(generated?.streamedImageLayout || []);
                const imageLayout = imageLayoutFromStream.length > 0
                    ? imageLayoutFromStream
                    : [{ image_id: 'img_1', url: imageParts[0]?.image_url?.url || '', placement: 'after_paragraph:1' }];
                const defaultAssistantText = `${getToastMessage('ui.generatedImageForYou')}\n\n**${getToastMessage('ui.imageDescription')}：** ${localizedDescription}`;
                const streamedTextRaw = String(generated?.streamedText || '').trim();
                const preferredStreamedText = streamedTextRaw && streamedTextRaw.includes(getToastMessage('ui.imageDescription'))
                    ? streamedTextRaw
                    : '';
                const assistantText = (preferredStreamedText || defaultAssistantText).trim() || defaultAssistantText;
                const imagePayload = {
                    content: assistantText,
                    image_parts: imageParts,
                    image_layout: imageLayout
                };
                renderMessageContent(contentDiv, imagePayload, null, true);
                assistantMessage.content = assistantText;
                assistantMessage.image_parts = imageParts;
                assistantMessage.image_layout = imageLayout;
                assistantMessage.image_description = localizedDescription;
                assistantMessage.generated_image_prompt = englishPrompt;

                const messages = chats[chatIdForRequest].messages;
                if (messages.length > 0 && messages[messages.length - 1].role === 'assistant') {
                    messages[messages.length - 1] = assistantMessage;
                }
                recordImageGenerationUsageSuccess(originalUrl || displayUrl, {
                    expectedBase: imageUsageBase,
                    token: imageUsageToken
                });
                activeResponses.delete(chatIdForRequest);

                resolve(assistantMessage);
            } catch (error) {
                activeResponses.delete(chatIdForRequest);
                console.error(`${getToastMessage('console.imageLoadFailed')}:`, finalImageUrl || imageUrl, error.message);
                const errorMessage = getToastMessage('errors.imageGenerationFailed');
                renderMessageContent(contentDiv, errorMessage);
                assistantMessage.content = errorMessage;
                delete assistantMessage.image_parts;
                delete assistantMessage.image_layout;
                delete assistantMessage.image_description;

                const messages = chats[chatIdForRequest].messages;
                if (messages.length > 0 && messages[messages.length - 1].role === 'assistant') {
                    messages[messages.length - 1] = assistantMessage;
                }

                // 保存错误状态到缓存
                if (!currentUser) {
                    await saveChatsToDB('guest', chats);
                } else {
                    await saveChatsToDB(currentUser.id, chats);
                }

                resolve(assistantMessage);
            }
        };

        loadImage();
    });
}

let periodicSyncIntervalId = null;

function startPeriodicSync() {
    if (!currentUser) return;
    if (periodicSyncIntervalId) return;

    periodicSyncIntervalId = setInterval(async () => {
        try {
            if (typeof navigator !== 'undefined' && navigator.onLine === false) {
                return;
            }
            if (!currentUser) {
                if (periodicSyncIntervalId) {
                    clearInterval(periodicSyncIntervalId);
                    periodicSyncIntervalId = null;
                }
                return;
            }
            const result = await makeApiRequest('chats/conversations');
            if (result.success) {
                const serverChatIds = new Set(result.conversations.map(conv => conv.id));
                const localChatIds = Object.keys(chats).filter(id => !String(id).startsWith('temp_'));
                const deletedChatIds = localChatIds.filter(chatId => !serverChatIds.has(chatId));

                if (deletedChatIds.length > 0) {

                    for (const chatId of deletedChatIds) {
                        if (activeResponses.has(chatId) || (currentChatId === chatId && isProcessing)) {
                            continue;
                        }
                        delete chats[chatId];
                    }

                    await saveChatsToDB(currentUser.id, chats);

                    renderSidebar();
                }
            }
        } catch (error) {
            console.warn('Periodic sync failed:', error);
        }
    }, 5 * 60 * 1000);

    addGlobalCleanup(() => {
        if (periodicSyncIntervalId) {
            clearInterval(periodicSyncIntervalId);
            periodicSyncIntervalId = null;
        }
    });
}

const CHAT_LIST_SYNC_COOLDOWN_MS = 4000;
let chatListSyncInFlight = null;
let chatListSyncLastRunAt = 0;

async function syncChatListFromServer(options = {}) {
    if (!currentUser) return;
    if (typeof navigator !== 'undefined' && navigator.onLine === false) return;

    const force = !!options.force;
    const now = Date.now();
    if (!force && (now - chatListSyncLastRunAt) < CHAT_LIST_SYNC_COOLDOWN_MS) {
        return;
    }
    if (chatListSyncInFlight) {
        return chatListSyncInFlight;
    }

    chatListSyncInFlight = (async () => {
        try {
            const result = await makeApiRequest('chats/conversations', {
                suppressAutoLogout: true,
                timeoutMs: CHAT_HISTORY_SYNC_TIMEOUT_MS,
                retries: 0
            });
            if (!result?.success || !Array.isArray(result.conversations)) {
                return;
            }

            const serverChats = {};
            for (const conv of result.conversations) {
                if (!conv || !conv.id) continue;
                serverChats[conv.id] = {
                    id: conv.id,
                    title: conv.title,
                    model_name: conv.model_name,
                    created_at: conv.created_at,
                    updated_at: conv.updated_at,
                    last_device_fp: conv.last_device_fp || null,
                    isBridge: !!conv.is_bridge,
                    parent_chat_id: conv.parent_chat_id || null,
                    bridge_enabled: conv.bridge_enabled ? 1 : 0,
                    messages: []
                };
            }

            const serverChatIds = new Set(Object.keys(serverChats));
            const localChatIds = Object.keys(chats || {}).filter(id => !String(id).startsWith('temp_'));
            const deletedChatIds = localChatIds.filter(chatId => !serverChatIds.has(chatId));
            let hasChanged = false;
            let removedCurrentChat = false;

            for (const chatId of deletedChatIds) {
                if (activeResponses.has(chatId) || (currentChatId === chatId && isProcessing)) {
                    continue;
                }
                if (currentChatId === chatId) {
                    removedCurrentChat = true;
                    currentChatId = null;
                }
                delete chats[chatId];
                try { localStorage.removeItem(`pending_chat_${chatId}`); } catch (_) { }
                hasChanged = true;
            }

            for (const [chatId, serverChat] of Object.entries(serverChats)) {
                const localChat = chats[chatId];
                if (!localChat) {
                    chats[chatId] = {
                        ...serverChat,
                        messages: [],
                        docAttachments: [],
                        bridge_settings: serverChat.isBridge
                            ? {
                                objective: '',
                                systemPrompt: '',
                                notes: '',
                                includeParentContext: true,
                                parentContextTurns: BRIDGE_PARENT_CONTEXT_TURNS_DEFAULT
                            }
                            : undefined
                    };
                    hasChanged = true;
                    continue;
                }

                if ((localChat.title || '') !== (serverChat.title || '')) {
                    localChat.title = serverChat.title;
                    hasChanged = true;
                }
                if ((localChat.model_name || '') !== (serverChat.model_name || '')) {
                    localChat.model_name = serverChat.model_name;
                    hasChanged = true;
                }
                if ((localChat.created_at || '') !== (serverChat.created_at || '')) {
                    localChat.created_at = serverChat.created_at;
                    hasChanged = true;
                }
                if ((localChat.updated_at || '') !== (serverChat.updated_at || '')) {
                    localChat.updated_at = serverChat.updated_at;
                    hasChanged = true;
                }
                if ((localChat.last_device_fp || null) !== (serverChat.last_device_fp || null)) {
                    localChat.last_device_fp = serverChat.last_device_fp || null;
                    hasChanged = true;
                }
                if (!!localChat.isBridge !== !!serverChat.isBridge) {
                    localChat.isBridge = !!serverChat.isBridge;
                    hasChanged = true;
                }
                if ((localChat.parent_chat_id || null) !== (serverChat.parent_chat_id || null)) {
                    localChat.parent_chat_id = serverChat.parent_chat_id || null;
                    hasChanged = true;
                }
                if ((localChat.bridge_enabled ? 1 : 0) !== (serverChat.bridge_enabled ? 1 : 0)) {
                    localChat.bridge_enabled = serverChat.bridge_enabled ? 1 : 0;
                    hasChanged = true;
                }
                if (!Array.isArray(localChat.messages)) {
                    localChat.messages = [];
                    hasChanged = true;
                }
                if (!Array.isArray(localChat.docAttachments)) {
                    localChat.docAttachments = [];
                    hasChanged = true;
                }
            }

            const deviceFingerprint = await getDeviceFingerprint().catch(() => null);
            const triggerRemoteMessageSync = () => {
                syncChatsFromOtherDevice(serverChats, chats, deviceFingerprint).catch(() => { });
            };

            if (!hasChanged) {
                triggerRemoteMessageSync();
                return;
            }

            await saveChatsToDB(currentUser.id, chats);
            renderSidebar();
            triggerRemoteMessageSync();

            if (removedCurrentChat) {
                welcomePageShown = false;
                showEmptyState();
                routeManager.navigateToHome({ replace: true });
            }
        } catch (error) {
            console.warn('Foreground chat list sync failed:', error);
        } finally {
            chatListSyncLastRunAt = Date.now();
            chatListSyncInFlight = null;
        }
    })();

    return chatListSyncInFlight;
}

